programs.sol:
"""A contextual line-boundary detector.

Predict strong positive activity for standalone newlines, decaying with document
position and the number of earlier line breaks. Adjust for the preceding token's
word/script category and whether the line looks like code, chat, or a heading.
A fused period + curly closing quote + newline also gets a strong response.
Other newline spellings are weaker; initial Markdown headings are positive and
literal chat role/marker tokens get small corrections. Ordinary words predict 0.
State resets at document boundaries. Vocabulary-specific variation is omitted.
"""

import math
import unicodedata

FUNCTION_WORDS = frozenset(
    (
        "a an the of to in on at for from with by and or but as if that "
        "this these those is are was were be been being have has had do "
        "does did not no it its you your we our they their he his she her "
        "which who when where how any all some each most more than into "
        "over under about without within"
    ).split()
)
CODE_LITERALS = frozenset(
    (
        "true false True False None null nil nullptr else return break "
        "continue pass string int bool float double void err ok"
    ).split()
)
READS = ()


def previous_class(s):
    t = s.strip()
    if not t:
        return "space"
    if t in ("<|im_end|>", "<|endoftext|>"):
        return "message_end"
    if t in ("assistant", "user", "system"):
        return "role"
    if t == "<tool_call>":
        return "tool_call"
    if t.startswith("<") and t.endswith(">"):
        return "tag"
    if t in CODE_LITERALS:
        return "code_literal"
    if t.startswith(".") and t[1:].isalpha():
        return "extension"
    if t.lower() in FUNCTION_WORDS:
        return "function_word"
    if t.isdigit():
        return "number"
    if any("\u3400" <= c <= "\u9fff" or "\u3040" <= c <= "\u30ff" for c in t):
        return "east_asian"
    if any("CYRILLIC" in unicodedata.name(c, "") for c in t):
        return "cyrillic"
    if t.isalpha() and t.isascii():
        return "latin_word"
    if all(not c.isalnum() for c in t):
        return "punctuation"
    return "other"


# Corrections for the immediately preceding token's readable text category.
ENDING_ADJUSTMENT = {
    "code_literal": -0.123,
    "cyrillic": -0.201,
    "east_asian": -0.060,
    "extension": -0.138,
    "function_word": 0.251,
    "message_end": 0.345,
    "number": -0.110,
    "other": -0.062,
    "punctuation": -0.174,
    "role": -0.127,
    "space": -0.260,
    "tag": -0.046,
    "tool_call": 0.236,
}

# Corrections for the line as a whole: ordinary lines and first lines.
LINE_ADJUSTMENT = {
    "chat": (-0.182, -0.640),
    "code": (-0.166, -0.296),
    "east_asian": (-0.230, -0.289),
    "heading": (-0.440, -0.363),
}


CODE_WORDS = frozenset(
    (
        "import export from include define class public private protected "
        "static final const let var function def async await return package "
        "namespace using try except catch while for if else elif do switch "
        "case break continue print printf echo sudo cd git python bash node"
    ).split()
)


def line_style(text):
    t = text.strip()
    if not t:
        return "empty"
    if "<|" in t or t.startswith(("<tool", "</tool")):
        return "chat"
    if t.startswith("#"):
        return "heading"
    if "```" in t:
        return "code"
    if any(ch in t for ch in "_={}[]()\\<>/@$"):
        return "code"
    if t.split()[0] in CODE_WORDS:
        return "code"
    if any("\u3400" <= c <= "\u9fff" or "\u3040" <= c <= "\u30ff" for c in t):
        return "east_asian"
    return "plain"


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        pos, lines, prev, line = 0, 0, "", ""
    else:
        _, pos, lines, prev, line = carry
    s = prefix.token_strings[-1]
    opening = 1 / math.sqrt(1 + pos)
    value = 0.0
    if s == "\n":
        value = 0.117 + 1.095 * opening
        value += 0.509 / math.sqrt(1 + lines)
        value += ENDING_ADJUSTMENT.get(previous_class(prev), 0.0)
        ordinary, first = LINE_ADJUSTMENT.get(line_style(line), (0.0, 0.0))
        value += ordinary
        if lines == 0:
            value += 0.377 + first
        if pos == 0:
            value = 1.71
    elif s == "\n\n":
        value = -0.059 + 0.539 * opening
    elif s in (".”\n", ".”\n\n"):
        # A sentence's typographic closing quote, followed by a line break.
        if s.count("\n") == 1:
            value = 0.965 + 1.572 * opening
        else:
            value = 0.324 + 0.444 * opening
    elif s == ".\n\n":
        value = 0.073 - 0.438 * opening
    elif "\n" in s:
        value = -0.025 + 0.20 * opening
    elif s in ("#", "##", "###"):
        if pos == 0:
            value = {"#": 1.16, "##": 0.58, "###": 0.77}[s]
        else:
            value = 0.02 + 0.20 * opening
    elif s in ("<|im_start|>", "<|im_end|>", "<|endoftext|>"):
        value = -0.07
    elif s in ("user", "assistant", "system"):
        value = -0.11
    elif s == "</think>":
        value = 0.15
    elif s in ("<tool_response>", "</tool_response>", "<tool_call>", "</tool_call>"):
        value = -0.05
    # Keep only this line, not the growing document prefix.
    line = (line + s).rsplit("\n", 1)[-1]
    return (doc, pos + 1, lines + s.count("\n"), s, line), float(value)

"""A word-family detector for draw / extract / pull / take.

It gives negative pulses for these words in any sense, including code. Chinese
and Japanese pulling/taking words have similar pulses; 抽 is especially strong.
Retrieval, removal, absorption and selection words are weaker relatives.
Split inflections and an immediately following article or particle can inherit
some of a pulse, as can a Chinese character completing a strong extraction
compound. Strong lexical pulses are larger at a document's start. Other small
token-specific effects are intentionally omitted.
"""
import re

READS = ()

# Real lexical families, not token IDs. The numbers are fitted pulse sizes.
CJK = (
    (8.9, '抽'), (7.4, '抽取'), (6.5, '抽出'),
    (3.5, '提取 汲取 吸取 抽查'), (3.2, '吸 吸引'),
    (2.3, '抜 拉动 取出 掏出 薅 拔 引き 抽象 抽奖 抽烟 掏'),
    (1.5, '取 摘 吸引力 を取り 拿出 榨 吸收 捞 提款 抠 撥'),
    (1.1, '引 取り 吸入 拉 拿 抓 抓住 下载 提出 出来 获取'),
    (0.9, '得出 搜集 拆除 魅力'),
    (0.65, '画 绘画 绘制 取得'), (0.4, '出 出了 出來'),
)
EAST_ASIAN = {s: a for a, words in CJK for s in words.split()}


def magnitude(word):
    if re.fullmatch(r'(?:draw(?:s|n|ing|ings|er|ers)?|drew|'
                    r'withdraw(?:s|n|ing|al|als)?|withdrew|'
                    r'extract(?:s|ed|ing|ion|ions|or|ors)?)', word):
        return 4.0
    if re.fullmatch(r'pull(?:s|ed|ing)?', word):
        return 2.7
    if word.startswith('sketch'):
        return 2.0
    if re.fullmatch(r'(?:grab(?:s|bed|bing)?|attract(?:s|ed|ing)?)', word):
        return 1.6
    if word.startswith(('retriev', 'fetch')) or word == 'attractive':
        return 1.3
    if word.startswith(('remov', 'abstract', 'download', 'deriv',
                        'gather', 'absorb', 'deduct', 'subtract', 'glean',
                        'withhold', 'withheld')):
        return 0.9
    if word.startswith('suck') or word in {
        'uptake', 'absorption', 'orption', 'suction', 'excerpt', 'retreat'
    }:
        return 0.8
    if word in {'take', 'takes', 'taking', 'taken', 'took'}:
        return 0.55
    if word.startswith(('pick', 'select', 'collect', 'attraction')):
        return 0.3
    return EAST_ASIAN.get(word, 0.0)


def step(carry, prefix, upstream):
    raw = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    reset = carry is None or carry[0] != doc
    pulse, previous = (0.0, '') if reset else carry[1:]
    word = raw.strip().lstrip('._/(-').lower()
    value = magnitude(word)
    joined = bool(raw) and not raw[0].isspace()
    if joined and word in {'rawing', 'rawn', 'rawer'}:
        value = 2.5
    if joined and word in {'tract', 'tracted', 'traction', 'tracts',
                           'tractor', 'tractive', 'straction', 'etch', 'etched'}:
        value = 1.5
        if previous.endswith('ex') and word.startswith('tract'):
            value = 3.0 if word == 'traction' else 4.0
    lexical = value
    suffix = joined and word in {'s', 'ed', 'ing', 'ings', 'n', 'al', 'or', 'ors'}
    if suffix and pulse >= 0.7:
        value = max(value, pulse * (0.6 if word == 'ings' else 0.85))
    elif pulse >= 0.3:
        fraction = {' a': 0.2, ' the': 0.2,
                    ' of': 0.4, ' down': 0.25}.get(raw, 0)
        value = max(value, fraction * pulse)
        if raw == ' out':
            value = max(value, 0.85 if pulse < 1.5 else 1.7)
    # A following Chinese character can complete a strong extraction compound.
    if pulse >= 6.0 and word and all('\u4e00' <= c <= '\u9fff' for c in word):
        value = max(value, 0.16 * pulse)
    if reset and lexical >= 1.5:
        value *= 1.25
    return (doc, value if lexical or suffix else 0.0, word), -float(value)

programs.luna:
"""Flag words about taking, drawing, pulling, or removing something.

This is a sparse lexical approximation: it recognizes overt action words, not
the surrounding sentence or the thing being moved.
"""

READS = ()

DRAW_OR_EXTRACT = {
    "draw", "drawing", "draws", "drew", "drawn",
    "extract", "extracted", "extracting", "extraction",
}

PULL_OR_ATTRACT = {
    "pull", "pulls", "pulled", "pulling", "attract", "attracts",
    "attracted", "attracting", "attraction", "吸引",
}

MEDIUM = {
    "sketch", "sketches", "sketched", "sketching",
    "grab", "grabs", "grabbed", "grabbing",
    "retrieve", "retrieves", "retrieved", "retrieving",
    "subtract", "subtracts", "subtracted", "subtracting",
    "uptake", "deplete", "depleted", "depleting", "depletion",
    "absorb", "absorbs", "absorbed", "absorbing", "absorption",
    "gathering", "athering", "画",
}

ACTION = {
    "take", "takes", "took", "taken", "taking",
    "grab", "grabs", "grabbed", "grabbing",
    "pick", "picks", "picked", "picking",
    "select", "selects", "selected", "selecting", "selection",
    "remove", "removes", "removed", "removing", "removal",
    "subtract", "subtracts", "subtracted", "subtracting",
    "download", "downloads", "downloaded", "downloading",
    "abstract",
}

CHINESE = {
    "取", "奪", "减", "削", "提出", "提出的",
}


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().casefold()
    if word in DRAW_OR_EXTRACT:
        return None, -4.1
    if word in PULL_OR_ATTRACT:
        return None, -2.8
    if word in MEDIUM:
        return None, -1.2
    if word in ACTION or word in CHINESE:
        return None, -0.8
    return None, 0.0

programs.sol:
"""A language-sensitive phrase-comma detector.

Japanese clause commas are strongest, especially after grammatical particles;
Chinese enumeration commas are weak. English commas get a larger response
after discourse connectives, introductory phrases, and function words than
after names, numbers, or word fragments. A small Japanese-script background
is retained; other word-specific activations are deliberately omitted.
Only a bounded text history is kept, reset at each document boundary.
"""
import re

READS = ()
STRONG_CONNECTIVES = {
    'however', 'moreover', 'furthermore', 'additionally',
    'nevertheless', 'nonetheless',
}
TRANSITIONS = {
    'therefore', 'thus', 'hence', 'consequently', 'accordingly',
    'alternatively', 'finally', 'similarly', 'likewise', 'meanwhile',
    'otherwise', 'instead', 'also', 'ultimately', 'specifically',
}
INTERJECTIONS = {'yes', 'no', 'well', 'wait', 'hmm', 'okay', 'ok', 'yeah'}
CONTINUERS = {'so', 'now', 'then', 'yet', 'but', 'still', 'rather', 'again'}
OPENERS = {
    'in', 'on', 'at', 'for', 'as', 'after', 'before', 'with', 'by',
    'if', 'when', 'while', 'although', 'despite', 'since', 'from', 'once',
}
INTRODUCTIONS = (
    'for example', 'for instance', 'in addition', 'in particular',
    'in fact', 'on the other hand', 'in other words', 'as a result',
)


def has_hiragana(text):
    return any('\u3040' <= c <= '\u309f' for c in text)


def comma_value(history, previous):
    if previous and previous[-1].isdigit():
        return -0.025
    match = re.search(r'([^\W\d_]+)$', history)
    word = match.group() if match else ''
    low = word.lower()
    if low in STRONG_CONNECTIVES:
        return 2.38 if word[0].isupper() else 1.92
    if low in TRANSITIONS:
        return 1.73
    if low in INTERJECTIONS:
        return 1.05
    if low in CONTINUERS:
        return 1.5 if word[0].isupper() else 1.05
    phrase = re.split(r'[.!?;\n]', history)[-1].strip()
    if any(phrase.lower().endswith(p) for p in INTRODUCTIONS):
        return 1.42
    if low in {'case', 'cases', 'study', 'paper', 'embodiment', 'instance'}:
        return 1.0
    if phrase.lower().endswith(('of course', 'that is', 'that said')):
        return 0.92
    words = re.findall(r'[A-Za-z]+', phrase)
    if words and words[0].lower() in OPENERS and len(words) <= 10:
        return 0.62
    if low in {'this', 'that', 'which', 'what', 'when', 'where', 'here'}:
        return 0.8
    if low in {'is', 'are', 'was', 'were', 'said', 'say', 'says'}:
        return 0.75
    if low in {'it', 'them', 'him', 'her', 'me', 'you', 'us', 'all', 'there'}:
        return 0.55
    if low.endswith('ly'):
        return 0.9
    if not word:
        return 0.0
    if len(word) == 1:
        return -0.075
    if not word.isascii():
        return 0.4
    if word[0].isupper():
        return 0.0
    return 0.28 if previous[:1].isspace() else 0.1


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    history = '' if carry is None or carry[0] != doc else carry[1]
    previous = prefix.token_strings[-2] if history else ''
    token = prefix.token_strings[-1]
    japanese = any('\u3040' <= c <= '\u30ff' for c in history[-100:])
    value = 0.0
    if token == '、':
        if not japanese:
            value = -0.05
        elif previous in {'しかし', 'また', 'さらに', 'なお', 'ただ'}:
            value = 7.3
        elif previous.endswith(('は', 'が', 'に', 'で', 'と', 'ので')):
            value = 6.7
        else:
            value = 6.0 if has_hiragana(previous) else 4.3
    elif token == '、「':
        value = 3.4
    elif token == '，':
        value = 2.7 if has_hiragana(previous) else 0.85
    elif '，' in token:
        value = 0.35
    elif token == '،':
        value = 0.21
    elif token == ',':
        value = comma_value(history, previous)
    elif japanese:
        if token and all('\u4e00' <= c <= '\u9fff' for c in token):
            value = 0.35
        elif token.startswith('。'):
            value = 0.5
    return (doc, (history + token)[-160:]), float(value)

programs.luna:
"""Estimate comma responses, stronger after sentence-level transition words."""

READS = ()

TRANSITIONS = (
    "however", "therefore", "thus", "yet", "finally",
    "alternatively", "so", "yes",
)


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    suffix = "" if carry is None or carry[0] != doc else carry[1]
    token = prefix.token_strings[-1]
    before = suffix.rstrip().lower()

    if token == "、":
        value = 2.44
    elif token in (",", "،"):
        value = 0.19
        if before.endswith("in this study") or before.endswith("in this paper"):
            value = 0.54
        elif token == "," and any(before.endswith(word) for word in TRANSITIONS):
            value = 0.60
    else:
        value = 0.0

    return (doc, (suffix + token)[-80:]), value

programs.sol:
"""Approximate a response dominated by tokenized equals/assignment signs.

A standalone '=' is strongly negative, especially after a one-letter alphabetic
token or near a document's beginning (except its very first token). Longer
preceding tokens and recent code punctuation soften that response. Closing
delimiters fused to '=' are also negative. Comparison operators stay near zero;
other assignment forms get smaller signed responses. Ordinary text is left at
a near-zero baseline rather than given a lexical lookup table.

Keep only the preceding token, 60 recent characters, and document position;
reset them at every document boundary.
"""
READS = ()


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        recent, previous, position = '', '', 0
    else:
        _, recent, previous, position = carry
    raw = prefix.token_strings[-1]
    token = raw.strip(' \t')
    prev = previous.strip()
    value = -0.002
    if token == '=':
        if position == 0:
            value = -0.29
        else:
            value = -1.01 + 0.032 * min(len(prev), 12)
            if len(prev) == 1 and prev.isalpha():
                value -= 0.20
            if position < 16:
                value -= 0.14
            if '_' in recent:
                value += 0.09
            if any(c in recent for c in ';{}\"\''):
                value += 0.09
    elif token == '＝':
        value = -1.2
    elif token.endswith('=') and token[:-1] in (')', ']', '}', "'"):
        value = -0.90
    elif token.endswith('=') and token[:-1] in ('+', '-', '*', '/', '%'):
        value = -0.36
    elif token.endswith('=') and token[:-1] in ('&', '|', '^'):
        value = -0.70
    elif token == ':=':
        value = 0.02 + 0.02 * min(len(prev), 10)
    elif token == '<-':
        value = 0.61
    elif token.strip() == '=' and '\n' in token:
        value = -0.29
    elif token in ('="', "='", '=[', '={'):
        value = 0.18
    carry = (doc, (recent + raw)[-60:], raw, position + 1)
    return carry, float(value)

programs.luna:
"""Detect the four recurring relational words in the examples, with larger
outputs for 'between' and 'about'. Other text receives zero.
"""
READS = ()
VALUES = {"about": 1.3, "between": 2.4, "both": 1.5, "against": 1.1}

def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().casefold()
    return None, float(VALUES.get(word, 0.0))

programs.sol:
"""Short q/Q fragments, with weaker question/query/quantity vocabulary.

Bare q/Q and short identifiers not spelling 'qu' produce strong responses.
Most ordinary 'qu' words do not. A small vocabulary covers questions,
requests, queues, quality and quantities, including a few translations.
Arabic qaf and fullwidth q/Q are recognized. Recent text distinguishes
q attached to a word from q completing a LaTeX command; letters and digits
immediately after an ASCII q fragment retain a small response. This is a
compact approximation, omitting many token-specific and contextual details.
"""
import re

READS = ()

# Familiar abbreviations, rather than a table of vocabulary-token IDs.
ABBREVIATIONS = {
    'eq': 3.0,   # equality
    'req': 3.0,  # request
    'sq': 4.1,   # square
    'iq': 6.0,   # intelligence quotient
    'hq': 6.0,   # headquarters
    'seq': 1.5,  # sequence
}

# Word families: case and punctuation are ignored for these weaker cues.
WORD_FAMILIES = (
    (('query', 'queries'), 0.9),
    (('request',), 0.85),
    (('queue',), 1.6),
    (('equality', 'inequalit'), 0.5),
    (('quality',), 1.1),
    (('quant',), 0.65),
    (('quite', 'quiet'), 0.75),
    (('quart',), 0.45),
    (('queen', 'queer'), 0.8),
    (('headquarters',), 1.0),
    (('quest',), 0.5),
)


def token_value(token):
    text = token.strip().replace('Ｑ', 'Q').replace('ｑ', 'q')
    lower = text.lower()
    if lower.startswith(('вопрос', 'запрос', 'pregunta', 'pergunta', 'frage')):
        return 0.7  # question/request words
    if any(w in lower for w in ('qualité', 'qualidade', 'qualität')):
        return 0.5
    letters = re.sub('[^a-zA-Z]', '', text)
    word = letters.lower()
    if 'q' in word:
        if set(word) == {'q'}:
            if len(word) > 1:
                return 4.8
            return 4.0 if token[:1].isspace() else 4.5
        if word in ABBREVIATIONS:
            return ABBREVIATIONS[word]
        if word.endswith('eq') and len(word) > 3:
            return 0.2  # longer equality operators, e.g. subseteq
        if word.endswith('q'):
            if len(word) == 2:
                return 3.8 if token[:1].isspace() else 4.9
            return 3.0 if len(word) == 3 else 1.5
        if 'sqrt' in word or word == 'qrt':
            return 0.0
        if 'sql' in word or 'graphql' in word:
            return 1.5
        if len(word) <= 3 and 'qu' not in word:
            return 1.9 if word in ('qt', 'qr') else 2.4
        if 'question' in word:
            value = 1.25 if 'questions' in word else 1.6
            return value + (0.3 if 'Question' in letters else 0.0)
        if word.startswith('equation'):
            return 0.3 if word.endswith('s') else 0.55
        for stems, value in WORD_FAMILIES:
            if any(stem in word for stem in stems):
                return value
        if word in ('qu', 'equ', 'squ', 'aqu'):
            return -0.15
        if word == 'que':
            return 0.05 if token[:1].isspace() else 0.3
        return 1.1 if re.search('q(?!u)', word) else 0.0
    if word in ('ask', 'asks', 'asked', 'asking'):
        return 0.7 if token[:1].isspace() else 0.4
    if text == 'ق':
        return 2.4 if token[:1].isspace() else 1.7
    if 'ق' in text and text.endswith('ق') and len(text) <= 3:
        return 1.5
    if text in ('问', '問'):
        return 1.0
    if any(w in text for w in ('问题', '問題', '質問', '질문')):
        return 0.6
    if text in ('求', '请求', '要求', '需求', '请', '請'):
        return 0.65
    if text in ('量', '质量', '質量'):
        return 1.1 if len(text) > 1 else 0.5
    if text in ('队', '隊', '排队', '排隊'):
        return 1.4
    return 0.0


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    tail, previous = ('', '') if carry is None or carry[0] != doc else carry[1:]
    value = token_value(token)
    if token == 'q':
        match = re.search(r'(\\?)([A-Za-z]+)$', tail)
        if match:
            value = 2.3 if match[1] else (5.6 if len(match[2]) >= 4 else 5.1)
    if previous.strip().lower().endswith('q') and 'q' not in token.lower():
        if token[:1].isalpha():
            value = max(value, 0.48)
        elif token[:1].isdigit():
            value = max(value, 0.17)
        else:
            value = max(value, 0.05)
    return (doc, (tail + token)[-40:], token), float(value)

programs.haiku:
"""Component layers.0.mlp.down_proj:6022 is a "letter q" detector, with a weak
"question / ask / request" word tier.

It reads only the current token's text and writes a bump into the residual stream
when that token is the letter q (or Q), mainly when q is used on its own or as a
short code fragment:

  * bare q / Q, with or without a leading space or punctuation ("q", " Q", "(q", "/Q"):
    strong, about 4.5;
  * other very short tokens containing q ("iq", "QQ", "eq", "req", "ql", "qs"): medium, about 3.5 or 3;
  * "sql" and "seq": weak, about 1.5;
  * Arabic qaf (ق): weak, about 2;
  * the English words question, request, query, queue, quality (q followed by u,
    inside a longer word): weak, about 1;
  * words for asking or questions ("ask", "asked", "asking", "question", "问", "問題",
    "вопрос", "¿"): weak, about 0.7;
  * everything else is 0, including the ordinary spelling "qu" (que, quick, quite, qui),
    and longer words where q is not a letter of their own (equation, sqrt, square).

The value does not depend on earlier tokens or on context.
"""

READS = ()

WORDS_WITH_QU = ("question", "request", "query", "queue", "quality")
ASK_WORDS = {
    "ask", "asked", "asks", "asking", "question", "questions", "request", "requests",
    "requested", "query", "queries", "quality", "queue", "quiz", "quest",
    "问", "问题", "問", "問題", "请求", "請求", "求", "询问", "疑问", "质量", "高质量", "要求",
    "¿", "вопрос", "вопросы", "frage",
}


def _letters(text):
    return "".join(ch for ch in text.lower() if "a" <= ch <= "z")


def q_strength(text):
    """How much the token text looks like the letter q, from 0 to 4.5."""
    if "ق" in text:
        return 2.0
    word = _letters(text)
    if "q" not in word:
        return 0.0
    if word == "q":
        return 4.5
    if "qu" in word:
        return 1.0 if any(w in word for w in WORDS_WITH_QU) else 0.0
    if word in ("sql", "seq"):
        return 1.5
    if len(word) <= 2:
        return 3.5
    if len(word) == 3:
        return 3.0
    return 0.0


def step(carry, prefix, upstream):
    """Activation at the newest token: its q-strength, or the ask-word weight (carry unused)."""
    text = prefix.token_strings[-1]
    value = q_strength(text)
    if value == 0.0 and text.strip().lower() in ASK_WORDS:
        value = 0.7
    return None, float(value)

programs.luna:
"""Estimate q-fragment activations and weaker question, query, and SQL signals."""
READS = ()

def step(carry, prefix, upstream):
    raw = prefix.token_strings[-1]
    token = raw.strip()
    word = token.lower()
    if token == "q":
        return None, 3.8 if raw.startswith(" ") else 5.8
    if token == "Q":
        return None, 4.1
    if len(token) <= 3 and word.endswith("q"):
        return None, 4.5
    if word.startswith("question"):
        return None, 1.2
    if word.startswith("query"):
        return None, 0.85
    if word.startswith("ask") or word.startswith("request"):
        return None, 0.65
    if word == "sql":
        return None, 1.5
    if "q" in word:
        return None, 0.55
    return None, 0.0

programs.sol:
"""A spelling-level detector for approaches, challenges and methods.

Emit a strong negative pulse for 'approach' inflections, including split
words; 'appro' itself already responds. Novelty adjectives strengthen it.
Emit weaker pulses for difficulties, methods, French/Russian approach
spellings (including Russian noun/verb endings), and Chinese approach/
facing words. Certain following prepositions carry a pulse too. Russian 'при' and app paths are additional
surface triggers. All other activations are zero, omitting the component's
many weak background responses. State resets between documents.
"""
import re

READS = ()
APPROACH = {'approach', 'approached', 'approaches', 'approaching'}
CHALLENGE = {
    'challenge': -1.1, 'challenges': -1.55,
    'challenged': -1.0, 'challenging': -0.88,
}
METHODS = {'method', 'methods'}
TECHNIQUES = {'technique', 'techniques', 'methodology', 'methodologies'}
AVOIDANCE = {'avoid', 'avoided', 'avoiding', 'avoids', 'avoidance',
             'overcome', 'threatened'}
# Chinese approaching/facing, welcoming, forcing/pursuing, methods/challenges.
CHINESE = {
    '临': -2.05, '臨': -2.05, '面临': -2.20,
    '迎': -1.28, '迎来': -0.81, '迎接': -1.03,
    '逼': -0.83, '追': -0.76, '方法': -0.52, '挑战': -1.55,
}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous = carry[1] if carry is not None and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    word = token.strip().lower()
    # Join letter fragments, but never across whitespace or punctuation.
    match = re.search(r'[a-zа-я]+$', token.lower())
    tail = match.group() if match else ''
    joined = previous + tail if match and match.start() == 0 else tail
    value = 0.0
    if word in APPROACH:
        value = -5.62 if word in {'approaches', 'approaching'} else -6.04
        if previous in {'new', 'novel', 'innovative'}:
            value -= 0.85
    elif joined in APPROACH and previous and word != joined:
        value = -6.3
    elif word == 'appro':
        value = -3.7 if token.startswith(' ') else -4.2
        if token.strip().isupper():
            value = -3.05
    elif joined in {'approche', 'approches'}:
        value = -3.25
    elif word == 'подход':
        value = -2.96
    elif previous == 'подход' and token.isalpha():
        # Noun case/number endings versus verb/adjective continuations.
        endings = {'а', 'ов', 'ы', 'ах', 'ом', 'е'}
        value = -2.2 if word in endings else -1.1
    elif word == 'при':
        value = -0.61 if token == ' при' else -0.43
    elif word in CHINESE:
        value = CHINESE[word]
    elif token in {'/app', '.app', '.App'}:
        value = -1.6 if token.startswith('/') else -1.3
    elif word in CHALLENGE or joined in CHALLENGE:
        value = CHALLENGE.get(word, CHALLENGE.get(joined, 0.0))
    elif word in METHODS and token != word:
        # Bare lowercase 'method' usually names code rather than prose.
        value = -0.31
    elif word in TECHNIQUES or joined in TECHNIQUES:
        value = -0.70
    elif word in AVOIDANCE:
        value = -0.62
    elif previous in APPROACH and word in {'to', 'of', 'for'}:
        value = {'to': -2.25, 'of': -1.90, 'for': -0.25}[word]
    elif previous.startswith('challenge') and word in {'to', 'of', 'for', 'in'}:
        value = {'to': -0.7, 'of': -0.45, 'for': -0.33, 'in': -0.24}[word]
    return (doc, joined[-32:]), value

programs.luna:
"""Approximate activations from words about methods and challenges.

The harvested examples concentrate on approach, method, technique, and
challenge vocabulary. Their activations vary by context, so each word family
gets a typical modest negative value rather than a context-sensitive rule.
"""

READS = ()


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().casefold()
    if word.startswith("approach"):
        value = -5.9
    elif word == "appro":
        value = -4.0
    elif word == "подход":
        value = -3.2
    elif word.startswith(("method", "techniqu")):
        value = -0.8
    elif word.startswith("challeng"):
        value = -1.2
    elif word.startswith(("avoid", "overcom")):
        value = -0.7
    elif word.startswith(("threaten", "theoretic")):
        value = -0.6
    else:
        value = 0.0
    return None, float(value)

programs.sol:
"""Approximate a cross-token D-spelling signal.

Only adjacent tokens within one document are used. A preceding piece must
end in d/D or one of the listed counterparts in other scripts. Familiar
D-initial words and code roots give negative predictions (d|ata, d|iff).
Common grammatical endings are weaker; -ward, -able/-ible and Cyrillic
дж are positive exceptions. Script, case and accents refine the estimate.
Long preceding pieces damp it, while a preceding -ed strengthens it.
Small unrelated background activity and many fragment differences are omitted.
"""
import unicodedata
from functools import lru_cache

READS = ()
D_LETTERS = tuple('dDдДدδΔดＤ')
D_ROOTS = frozenset('data down diff disc draw def div dir del det dev dis dist '
                    'dict dim doc db dyn demo delta density'.split())
D_WORDS = frozenset('database download direct directory direction divide division '
                    'display district discover discard distinguish different '
                    'difference document doctor detect detection detail detailed '
                    'details develop development device delete deliver delay '
                    'design describe determine determined dollar domain dog dark '
                    'draft drag drop dump during dance date day diet digit'.split())
D_CLUSTERS = frozenset('da de di do du dr dy den der dem des dic dig die '
                        'dia dial dam dan dar don dot dst'.split())
SUFFIXES = frozenset('s ed ing ings er ers est ly tion ation tions ations '
                     'al ial ity ment ments ness less able ible ward wards'.split())
CYRILLIC_D_STEMS = frozenset('дав дв дел дев дет добр дост держ длин днев '
                            'дом дор док дум дух душ'.split())
ARABIC_D_STEMS = frozenset('دست دخل دخ دام دار دان دن دل دو ده در دق'.split())


@lru_cache(maxsize=32768)
def continuation_score(token):
    text = token.lower()
    first = text[:1]
    if first in {"'", '’'}:
        return 0.09
    if not first or not first.isalpha():
        return 0.0
    script = unicodedata.name(first, '')
    n = len(text)

    if 'LATIN' in script:
        plain = ''.join(c for c in unicodedata.normalize('NFD', text)
                        if not unicodedata.combining(c))
        spelling = 'd' + plain
        value = -0.08
        if n == 1:
            value -= 0.05
        elif n == 2:
            value -= 0.07
        elif n >= 4:
            value += 0.03
        if first in 'ei':
            value -= 0.11
        if spelling in D_ROOTS:
            value -= 0.85 + (0.89 if n >= 3 else 0.0)
        if spelling in {'def', 'div'}:
            value -= 0.41
        if spelling in D_WORDS:
            value -= 0.75
        if spelling in D_CLUSTERS:
            value -= 0.13
        if text in SUFFIXES:
            value += 0.12
        if text in {'able', 'ible'}:
            value += 0.19
        if text in {'ward', 'wards'}:
            value += 0.92
        if token[0].isupper() and not token.isupper():
            value += 0.13
        if plain != text:
            value -= 0.02
        return value

    if 'CYRILLIC' in script:
        value = -0.15
        if first in 'еэі':
            value -= 0.29
        if first == 'ж':
            value += 1.22
        if 'д' + text in CYRILLIC_D_STEMS:
            value -= 0.53
        return value
    if 'ARABIC' in script:
        return -0.29 - (0.43 if 'د' + text in ARABIC_D_STEMS else 0.0)
    if 'GREEK' in script:
        return -0.27 - (0.84 if first == 'ι' else 0.0)
    return 0.0


def step(carry, prefix, upstream):
    if prefix.position == 0:
        return None, 0.0
    if prefix.document_ids[-1] != prefix.document_ids[-2]:
        return None, 0.0
    previous = prefix.token_strings[-2]
    if not previous.endswith(D_LETTERS):
        return None, 0.0

    # A short preceding piece makes continuation more plausible than a long word.
    n = len(previous.strip())
    scale = 1.04
    scale -= 0.18 * (n >= 4) + 0.19 * (n >= 5) + 0.47 * (n >= 7)
    scale += 0.32 * previous.lower().endswith('ed')
    return None, float(scale * continuation_score(prefix.token_strings[-1]))

"""Approximate a token-final F feature using spelling and word boundaries.

An isolated f/F is moderate; a short fragment ending in f inside a word is
strong. Familiar English words and code forms are weaker than arbitrary
fragments. Internal f is weaker still, and word-initial f usually does not
fire. The same rough rule covers Cyrillic ф and Arabic ف. There are small
responses to ph, Greek phi, Japanese fu, and the f-shaped historical long s.
Only the preceding character and a short text tail are carried between tokens;
these are reset at document boundaries. This is not a token lookup table.
"""
import unicodedata

READS = ()
F_SPELLINGS = str.maketrans({'ф': 'f', 'Ф': 'F', 'ف': 'f'})
WHOLE_WORDS = frozenset('''
    self half staff stuff off proof brief chief belief relief grief
    roof leaf beef cliff scarf thief
'''.split())
CODE_FORMS = {
    'def': 1.6,
    'ref': 2.2,
    'diff': 1.8,
    'elif': 1.25,
    'endif': 1.25,
    'pdf': 2.1,
    'inf': 3.0,
}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    tail = carry[1] if carry is not None and carry[0] == doc else ''
    previous = tail[-1:]
    original = prefix.token_strings[-1]
    raw = unicodedata.normalize('NFKC', original)
    text = raw.strip().lstrip('._-/([{\'"#:=+<>,').translate(F_SPELLINGS)
    word = text.lower()
    marked = bool(raw.strip() and not raw.strip()[0].isalnum())
    spaced = raw[:1].isspace()
    joined = bool(previous.isalpha() and raw[:1].isalpha())
    value = 0.0

    # A few common complete words do not behave like f-bearing fragments.
    if raw.startswith('<|'):
        pass
    elif word in ('after', 'before', 'left', 'different', 'difference', 'difficult'):
        pass
    elif word.endswith('self') and word != 'self':
        pass
    elif word.endswith('f'):
        if word == 'of':
            value = 1.9 if joined else (-0.02 if spaced else 0.4)
            if text == 'Of' and not joined:
                value = 0.7
        elif word == 'if':
            value = 2.6 if joined else 1.4
            if text.isupper():
                value = 3.5 if joined else (1.8 if spaced else 3.1)
        elif word == 'f':
            value = 3.4 if joined else (1.25 if text.isupper() else 1.65)
            if joined and text.isupper():
                value = 3.9 if previous.isupper() else 2.6
            if previous.isdigit() and not spaced:
                value += 0.4
        elif word in WHOLE_WORDS:
            value = 1.5 if joined else 1.2
        elif word in CODE_FORMS:
            value = CODE_FORMS[word] + 0.4 * joined
        elif word == 'bf' and tail.endswith('math'):
            value = 1.2  # The end of LaTeX's bold-math command.
        elif word == 'auf':
            value = 2.7  # A common German preposition.
        elif word.endswith('ff'):
            value = 2.1
        else:
            value = 3.7 if len(text) <= 4 else 2.0
            value += 0.9 * joined
        value -= 0.3 * marked
        if 'ф' in original or 'Ф' in original:
            value -= 0.6
    elif 'f' in word:
        at = word.rfind('f')
        value = 0.03 if at == 0 else (0.65 if at <= 4 else 0.25)
        if at == 0 and not spaced:
            value = 0.25
    elif 'ph' in word:
        value = 1.1 if word.endswith('ph') else 0.35
    elif 'φ' in text or 'Φ' in text:
        value = 0.6
    elif 'フ' in text:
        value = 1.0
    elif 'ſ' in original:
        value = 0.65

    tail = (tail + raw)[-24:]
    if raw.endswith(('\\n', '\\t', '\\r')):
        tail += ' '
    return (doc, tail), float(value)

programs.haiku:
"""Layer-0 MLP unit 6025 of Qwen3-1.7B: an "f letter" detector.

The unit reads the current token only. It is silent on most tokens and fires on the
letter f (either case) inside a token:
  - strongest when the f ends the token: "if", "def", "ref", "pdf", "af", "nf", "DF", "(f";
    after a consonant it is stronger than after a vowel;
  - a bare "f" token fires too;
  - weaker when the f sits in the middle of a word or identifier ("dateFormat", "Afghan");
  - silent on a token that starts with f ("for", "from", "file"), on f right after
    punctuation mid-token, and on the common word "of".
"self" and "elf" give a weak response.

Values are typical activations (contribution size) in the model's units.
"""

READS: tuple[str, ...] = ()

VOWELS = "aeiou"
WEAK_ENDINGS = ("self", "elf")
SILENT_WORDS = {"of"}


def activation(token: str) -> float:
    word = token.strip().lower()
    if word in SILENT_WORDS or "f" not in word:
        return 0.0
    if word.endswith(WEAK_ENDINGS):
        return 0.7
    if word.endswith("f"):
        if len(word) == 1 or word[-2] in VOWELS:
            return 1.8
        return 2.5
    i = word.index("f")
    if i == 0 or word[i - 1] in " _-./(":
        return 0.0
    return 0.5


def step(carry, prefix, upstream):
    return None, float(activation(prefix.token_strings[-1]))

programs.sol:
"""Detect punctuation in Cyrillic text and conversational boundaries.

Recent letter scripts and a slower script average supply the language context.
Punctuation, spaces and numbers are boosted in Cyrillic text, with weaker
responses to other scripts. Chat labels and marker-following newlines have
separate document-start boosts. Words and markers predict zero. Markup
preserves script context; document changes reset it.
"""
import unicodedata

READS = ()

# Ordered punctuation classes and their strengths in Cyrillic prose.
PUNCTUATION = (
    ('«', 2.9), ('»', 1.5), ('–—', 1.9), ('-', 2.1),
    ('…', 1.3), (':;', 1.0), (',', .95), ('"“”„', 1.0),
    ("'‘’", .8), ('([', 1.25), (')]', .6), ('!?', .75),
    ('#', .7), ('/', .8), ('%', 1.0), ('$', 1.0),
    ('.', .3), ('|•', 1.2),
)

# Baseline, script-context strength, document-start strength.
LABELS = {'user': (.65, 2.0, 1.0), 'assistant': (-.1, .37, .2)}
NEWLINES = {
    '<|im_end|>': (.43, 1.4, .58),
    '<tool_call>': (.24, 0., .6),
    '<tool_response>': (.24, 0., .96),
    '<think>': (.21, .55, .43), '</think>': (.29, .65, .59),
    'user': (-.06, .55, .3), 'assistant': (.04, .33, .26),
}
EARLY_NEWLINE = {'<|im_end|>': .8, '<tool_call>': 1.0,
                 '<tool_response>': .2}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, '', 0, 0., 0., 0., False)
    _, previous, position, recent, context, other, seen = carry
    token = prefix.token_strings[-1]
    q = token.strip()
    letters = [c for c in token if c.isalpha()]
    language = .6 * recent + .4 * context + other
    boundary_language = .25 * recent + .75 * context + other
    start = 1 / (1 + position / 20)
    label = previous == '<|im_start|>' and token in LABELS
    value = 0.
    if label:
        base, strength, initial = LABELS[token]
        value = base + strength * boundary_language + initial * start
        if position <= 3:
            value += .13 if token == 'user' else .35
    elif token.isspace() and '\n' in token and previous in NEWLINES:
        base, strength, initial = NEWLINES[previous]
        value = base + strength * boundary_language + initial * start
        if position <= 3:
            value += EARLY_NEWLINE.get(previous, 0.)
    elif token.isspace():
        strength = .6 if '\n' in token else .75
        if token.count('\n') > 1:
            strength = .35
        elif '\n' not in token and len(token) > 1:
            strength = .07
        value = strength * language
    elif q.isdigit():
        value = .9 * language
    elif not letters and not token.startswith('<'):
        strength = 0.
        for symbols, weight in PUNCTUATION:
            if any(c in symbols for c in q):
                strength = weight
                break
        if '-' in q and token.startswith(' '):
            strength = 1.55
        if len(q) >= 3 and set(q) <= set('-*_'):
            strength = .5  # horizontal divider
        if q.count('.') >= 3:
            strength = 1.3
        elif '.' in q and '\n' in token:
            strength = .55 if token.count('\n') == 1 else .43
        script = context + other if '«' in q or '»' in q else language
        if q == '.':
            script = recent + other
        value = strength * script

    # Estimate script from ordinary letters, not tag names or role labels.
    if not token.startswith('<') and not label:
        if letters:
            names = [unicodedata.name(c, '') for c in letters]
            cyr = sum('CYRILLIC' in name for name in names) / len(letters)
            foreign = sum(
                .35 * ('HANGUL' in name)
                + .35 * ('LATIN' in name and ord(c) > 127)
                + .25 * ('ARABIC' in name)
                + .05 * any(s in name for s in ('CJK', 'HIRAGANA', 'KATAKANA'))
                for c, name in zip(letters, names)) / len(letters)
            if seen:
                recent = .5 * recent + .5 * cyr
                context = .8 * context + .2 * cyr
                other = .8 * other + .2 * foreign
            else:
                recent, context, other = cyr, cyr, foreign
            seen = True
        else:
            recent *= .8
    return (doc, token, position + 1, recent, context, other, seen), float(value)

programs.haiku:
"""Draft 3: two concepts. (1) Punctuation and digits inside Russian (Cyrillic) text fire, graded by
token type. (2) Chat-template turn boundaries: the role word 'user' after <|im_start|> and the newline
after <|im_end|>."""

CYRILLIC_LO, CYRILLIC_HI = "Ѐ", "ӿ"

def strength(tok):
    """How strongly a non-letter token fires inside Russian text."""
    s = tok.strip()
    if any(c in s for c in "-–—«»()[]|/"):
        return 1.7
    if s in (",", ";", ":", "?", "!"):
        return 0.9
    if s == "" or "\n" in tok:
        return 0.7
    if s.isdigit():
        return 0.6
    if s == ".":
        return 0.3
    return 0.0

def in_russian(prefix, window=30):
    """True where most letters of the recent text (same document) are Cyrillic."""
    n = len(prefix.token_ids)
    lo = max(0, n - 1 - window)
    while lo < n - 1 and prefix.document_ids[lo] != prefix.document_ids[-1]:
        lo += 1
    letters = [c for c in "".join(prefix.token_strings[lo:n - 1]) if c.isalpha()]
    if not letters:
        return False
    cyrillic = sum(CYRILLIC_LO <= c <= CYRILLIC_HI for c in letters)
    return cyrillic > len(letters) / 2

READS = ()

def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1]
    before = prefix.token_strings[-2] if len(prefix.token_strings) > 1 else ""
    if before == "<|im_start|>" and tok == "user":
        return None, 1.2
    if before == "<|im_end|>" and tok == "\n":
        return None, 0.55
    if in_russian(prefix):
        return None, strength(tok)
    return None, 0.0

programs.sol:
"""Approximate rare negative lexical peaks, especially 条/條 ('strip', classifier).

A standalone character or a fused counting phrase responds strongly; words
about conditions, laws, noodles or headlines respond less. The preceding token
softens 苗条 ('slender') and digit-numbered articles, but strengthens large or
indefinite counts. Smaller peaks occur for Korean 조 and English strip/stripe
and narrow-word families. Other tokens predict zero: this deliberately leaves
out the component's diffuse, low-amplitude activity. Levels were fitted on
training text, not computed from the model's weights.
"""
import re

READS: tuple[str, ...] = ()
CLASSIFIER_PHRASE = re.compile(
    r'第?[一二两三四五六七八九十百千万这那]+[条條]$'
)


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip()
    previous = ''
    if prefix.position and prefix.document_ids[-1] == prefix.document_ids[-2]:
        previous = prefix.token_strings[-2].strip()

    if word in ('条', '條'):
        value = -6.9 if word == '条' else -7.3
        if previous.endswith('苗'):
            value = -4.9 if word == '条' else -5.5
        elif previous and previous[-1].isdigit():
            value = -6.25
        elif previous.endswith(tuple('几多百千万亿余')):
            value = -8.0
    elif CLASSIFIER_PHRASE.fullmatch(word):
        numeral = word[:-1].removeprefix('第')
        value = -6.0
        if len(numeral) > 1:
            value = -4.7
