        if capital:
            value = 5.8
        elif spaced or not previous or not previous[-1].isalpha():
            value = 6.35
        elif previous.lower().endswith(('zh', 'sh')):
            value = 3.75  # Chinese-style consonant digraphs before eng.
        else:
            value = 5.35
    elif word == 'engineering':
        value = 5.8 if spaced else 5.0
    elif word.startswith('engineer'):
        value = 2.9 if capital or word.endswith('s') else 3.3
    elif word in ('engine', 'engines'):
        if raw.isupper():
            value = 5.1
        elif capital:
            value = 4.25
        elif token.startswith(('/', '(')):
            value = 3.1
        else:
            value = 3.35 if spaced else 5.2
    elif word.startswith(('english', 'england')):
        value = 1.05
    elif word.startswith('eng'):
        # -ength is a tail of length/strength, not an eng- beginning.
        value = 0.3 if word.startswith('ength') else 2.0
    elif word.endswith('eng') and len(word) <= 5:
        value = 1.9
    elif word == 'äng':
        value = 2.2
    elif word.startswith('äng'):
        value = 0.6
    elif word.startswith('angular'):
        value = 1.5 if spaced else 0.9
    elif word in ('angle', 'angles'):
