    elif word == 'ang':
        value = 1.13 if spaced or capital else 0.3
    elif word.startswith('ang'):
        value = 0.4
    elif word == 'ng':
        ending = previous[-1:]
        base = unicodedata.normalize('NFD', ending)
        if not spaced and len(base) > 1:
            value = 2.1 if base[0].lower() == 'e' else 0.95
        else:
