        else:
            value = 0.34 if boundary else 0.065
    elif word == 'ong':
        value = 0.31
    elif word == 'ering':
        if previous.lower().endswith('engine'):
            value = 4.4 if raw.isupper() else 3.7
        else:
            value = 0.23
    elif word == 'ngine':
        value = 3.8
    # Chinese: engineering, engine, and English-language words.
    elif token == '工程':
        value = 5.15
    elif token.startswith('工程'):
        value = 2.8
    elif token.endswith('引擎'):
        value = 2.9 if token == '引擎' else 1.7
    elif token in ('工', '程'):
        value = 0.75
    elif token.startswith(('英语', '英語')) or token == '英':
        value = 0.75
    elif token == 'エン':
