"""Estimate plural-word activations, more strongly when a noun phrase is evident."""
READS = ()

IRREGULAR_PLURALS = {
    "men", "women", "children", "people", "feet", "teeth",
    "mice", "geese", "oxen", "criteria", "phenomena", "data",
    "media",
}
