    "is", "was", "has", "does", "this", "his", "its", "us",
    "yes", "gas", "news", "series", "species", "business",
}
MODIFIERS = {
    "the", "these", "those", "some", "many", "several", "few",
    "both", "all", "other", "various", "multiple", "numerous",
    "more", "fewer", "their", "our", "your", "its", "certain",
    "each", "new", "remaining", "such", "different", "unique",
}
ADJECTIVE_ENDINGS = (
    "al", "ic", "ive", "ous", "ary", "ent", "ant", "ful",
    "less", "able", "ible", "ed", "ing",
)
NUMBER_CHARACTERS = set("零一二三四五六七八九十百千")
PUNCTUATION = " \t\r\n.,:;!?()[]{}\"'`"


