        len(word) > 2 and word.endswith("s") and word not in SINGULAR_S
    )

    start = max(0, prefix.position - 3)
    previous = []
    for i in range(start, prefix.position):
        if prefix.document_ids[i] == prefix.document_ids[-1]:
            previous.append(
                prefix.token_strings[i].strip().lower().strip(PUNCTUATION)
            )
    number = any(
        ch.isdigit() or ch in NUMBER_CHARACTERS
        for part in previous for ch in part
    )
    if word == "天":
        plural = number
    if not plural:
        return None, 0.0

    noun_phrase = number or any(part in MODIFIERS for part in previous[-2:])
    noun_phrase |= any(
        part.endswith(ADJECTIVE_ENDINGS) for part in previous[-2:]
    )
    if irregular:
        noun_phrase = True
    return None, 0.30 if noun_phrase else 0.06

programs.sol:
"""Predict spelling-continuation responses and a few lexical offsets.

The harvested large negative responses often split Deli, delinquent,
Delphi, or Delhi after 'del'. This program detects those splits, plus
weaker continuations after short fragments ending in e + consonant.
The negative magnitude fades with the next piece's length, increases
when its first three letters contain 'i', and changes with the previous
fragment's final consonant. Initial 'e' or 'a' offsets this negativity.

Separate rules cover protocol tags, parentheses, and several word
classes. Unrecognized tokens stay near zero. This is only a partial
approximation of the component's token-specific variation. The previous
token is ignored whenever the document changes.
"""
READS = ()

QUANTITY = frozenset('all both any no many much most more less'.split())
THINGS = frozenset('everything anything nothing'.split())
MISSING = frozenset('nil null none undefined nan'.split())
LIMITERS = frozenset('only without except'.split())


def lexical_offset(token):
    if token == '<tool_call>':
        return 0.165
    if token == '</think>':
        return -0.118
    if token in ('</tool_call>', '</tool_response>'):
        return -0.066
    if token == '<|im_end|>':
        return 0.029
    if token == '(':
        return -0.027
    if not token.startswith(' '):
        return -0.0005
    word = token.strip().lower()
    if word in QUANTITY:
        return 0.028
    if word in THINGS:
        return 0.068
    if word in ('others', 'etc'):
        return 0.123
    if word in ('earlier', 'later'):
        return -0.090
    if word in MISSING:
        return -0.050
    if word in LIMITERS:
        return -0.033
    if word in ('left', 'right'):
        return 0.038
    return -0.0005


def spelling_response(previous, token):
    stem = previous.strip().lower()
    s = token.lower()
    if not (s and s[0].isascii() and s[0].isalpha()):
        return None
    if not (2 <= len(stem) <= 3 and stem[-2] == 'e'
            and stem[-1] in 'bcdfghjklmnpqrstvwxyz'):
        return None
    if stem == 'del':
        if s in ('i', 'in', 'ia', 'hi', 'ic', 'ph', 'phi'):
            return -0.68
        if s == 'ir':
            return -0.44
    # The decay depends on the length of the new spelling piece.
    decay = max(0.0, (5 - len(s)) / 4)
    strength = 0.057
    if stem.endswith('el'):
        strength += 0.176
    elif stem.endswith('em'):
        strength += 0.104
    elif stem.endswith('en'):
        strength += 0.032
    elif stem.endswith('et'):
        strength += 0.055
    elif stem.endswith('er'):
        strength -= 0.030
    if 'i' in s[:3]:
        strength += 0.076
    value = -0.007 - decay * strength
    if s.startswith('e'):
        value += 0.113
    elif s.startswith('a'):
        value += 0.055
    return value


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    token = prefix.token_strings[-1]
    value = lexical_offset(token)
    if carry is not None and carry[0] == doc:
        spelling = spelling_response(carry[1], token)
        if spelling is not None:
            value = spelling
    return (doc, token), float(value)

