programs.sol:
"""Predict a spelling response centered on the fragment -ina.

Bare ina gets a strong positive value. Capitalization of its unfinished word
and the stem here raise it; nearby Romance function words lower it. Related
vowel-final fragments, a few non-Latin ina/na spellings, min- words, and info
get smaller values. Two isolated UTF-8 continuation bytes get a negative value.
Only 140 preceding characters are retained, resetting at document boundaries.
These approximate spelling rules leave other responses unmodeled.
"""
import re

READS = ()
ROMANCE_FUNCTION_WORDS = {
    'de', 'la', 'el', 'que', 'en', 'les', 'le', 'et', 'un', 'une', 'des',
    'du', 'los', 'las', 'por', 'para', 'da', 'do', 'uma',
}


def spelling_value(token):
    word = token.lower()
    bare = not token[:1].isspace()
    if bare and word.isalpha():
        if word == 'ina':
            return 2.6
        if word.endswith('ina') and len(word) <= 6:
            return 1.9 if word == 'mina' else (0.9 if token.islower() else 0.3)
        if len(word) in (3, 4) and word.endswith('na'):
            return 0.7 if word[-3] in 'eoy' else 0.22
        if word == 'na':
            return 0.21
        if word == 'ينا':
            return 1.0
        if word in {'نا', 'ナ', '나'}:
            return 0.35
        if word == '娜':
            return 0.8
        if word == 'ино':
            return 0.32
        if word.endswith('на') and len(word) <= 4:
            return 0.75 if word == 'ина' else 0.28
        if word == 'ino':
            return 0.51
        if word == 'ine':
            return 0.10
        if word == 'inal':
            return 0.28
        if word == 'inas':
            return 0.94
        if word == 'ilda':
            return 1.2
        if word == 'ico':
            return 0.20
        if word.endswith('a') and len(word) <= 4:
            if word.startswith('i') and word[1:-1] in {'m', 'c', 'd', 's', 'ss'}:
                return 0.50
            if len(word) == 3 and word[0] in 'aeiou' and word[1] not in 'aeiou':
                return 0.10
    stem = word.strip()
    if stem in {'min', 'mini', 'minor', 'minute'}:
        if stem == 'minor':
            return 0.65 if not bare else 0.36
        return {'min': 0.10, 'mini': 0.35, 'minute': 0.28}[stem]
    if stem == '나':
        return 0.5
    if stem == 'info':
        return 0.25
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    recent = carry[1] if carry is not None and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    value = spelling_value(token)
    # Qwen's base byte alphabet numbers bytes 0x80..0x9F as 222..253.
    # This arithmetic decodes that fixed encoding; it is not a token score table.
    token_id = int(prefix.token_ids[-1])
    if token == '\ufffd' and 222 <= token_id <= 253:
        byte = token_id - 94
        if 0x8A <= byte <= 0x8B:
            value = -0.55
    if token == 'ina':
        words = re.findall(r'[^\W\d_]+', recent)
        ending = re.search(r'[^\W\d_]+$', recent)
        stem = ending.group() if ending else ''
        romance = sum(w.lower() in ROMANCE_FUNCTION_WORDS for w in words)
        value = 2.6 + 0.65 * stem[:1].isupper()
        value += 1.05 * (stem.lower() == 'here')
        value -= 3.0 * romance / max(1, len(words))
        value = max(1.0, min(4.0, value))
    return (doc, (recent + token)[-140:]), float(value)

"""A spelling detector centered on Cyrillic х (kha) and Greek χ (chi).

The response is strongest for isolated letters, smaller for short Cyrillic
fragments containing х, and weaker after long preceding fragments.  Case
and neighboring vowels modulate it.  A few short Cyrillic letters and Latin
chi/X spellings get small responses; other tokens return zero.
"""
import unicodedata

READS = ()
VOWELS = frozenset('аеиоуыэюяё')
# Vowel+х: baseline and attenuation per extra preceding character.
ENDINGS = {
    'а': (3.35, 0.45),
    'е': (2.6, 0.05),
    'и': (1.7, 0.28),
    'у': (2.05, 0.0),
    'ы': (0.44, 0.0),
    'я': (0.88, 0.0),
}


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    text = token.strip()
    doc = prefix.document_ids[-1]
    t = prefix.position
    previous = prefix.token_strings[-2] if (
        t > 0 and prefix.document_ids[-2] == doc) else ''
    last = previous[-1:].lower()
    spaced = token[:1].isspace()
    prior_spaced = previous[:1].isspace()
    length = max(0, min(len(previous.strip()), 6) - 1)

    # Recover a chi letter completed by a byte-level continuation token.
    if '\ufffd' in token:
        completed = prefix.text_prefixes[-1][-1:]
        if completed in ('χ', 'Χ'):
            text = completed
    lower = text.lower()
    value = 0.0
    if lower == 'χ':
        nearby = ''.join(prefix.token_strings[i] for i in range(max(0, t-3), t)
                         if prefix.document_ids[i] == doc)
        greek = any('GREEK' in unicodedata.name(c, '') for c in nearby)
        value = 4.8 if text == 'Χ' else (4.0 if greek else 3.0)
        if last == '(':
            value = 2.4
    elif lower == 'х':
        if not previous:
            value = 4.7
        elif text == 'Х':
            value = 4.8 if previous.endswith('\n') else 4.2
        elif spaced:
            value = 3.7
        else:
            value = 3.4 - 0.48 * length + 0.9 * prior_spaced
            value -= {'и': 1.3, 'ы': 0.9, 'я': 0.4}.get(last, 0.0)
            value = max(0.8, value)
    elif len(lower) == 2 and 'х' in lower:
        if lower[0] == 'х' and lower[1] in VOWELS:
            value = 2.9
        elif lower[1] == 'х' and lower[0] in ENDINGS:
            base, loss = ENDINGS[lower[0]]
            value = base - loss * length
            if spaced:
                value *= 0.2
            elif lower in ('ах', 'их'):
                value += 0.3 * prior_spaced
                if lower == 'ах' and last == 'ш':
                    value += 1.3
            value = max(0.2, value)
    elif 'х' in lower and len(lower) <= 4:
        value = 0.8 if lower.endswith('ех') else 0.3
    elif lower in ('а', 'г', 'е'):
        value = 0.8 if spaced and lower != 'е' else 0.3
        if lower == 'г' and not spaced:
            value = 0.45
        if not spaced and last == 'х':
            value += 1.1
    elif lower.endswith('chi') and len(lower) <= 4:
        value = 0.62 if spaced else 0.85
    elif text == 'X':
        value = 0.2
    return None, float(value)

programs.haiku:
"""Component layers.0.mlp.down_proj:6039: a Cyrillic/Greek "kh" letter detector.

What it does: the component's activation is large on the letter х (Cyrillic ha, which
sounds like English "h" in "loch" / Russian "х"), Х, and the Greek chi χ/Χ. It is
largest when that letter is a token on its own (" х", "Х", "χ"), and when a
standalone х is spelled as two byte tokens (the completing byte is scored).
It is also high on the short syllables that end or start with х (-ах, -ех, -их,
-ух, хи, хо, ха), and weakly on the other pieces of a word that contains х.
Everything else is about zero.

The values are the average activation per class on training text, rounded.
"""

READS = ()

KH = set("хХχΧ")  # the kh letters: Cyrillic х/Х, Greek χ/Χ


def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1]
    prev = prefix.token_strings[-2] if len(prefix.token_strings) > 1 else ""
    if "�" in tok and prefix.text_prefixes[prefix.position][-1:] in KH:
        return None, 3.6  # last byte of a х/χ that is split across tokens
    if tok.strip() in ("Х", "χ", "Χ"):
        return None, 4.0  # capital or Greek chi on its own
    if tok == " х":
        return None, 3.6  # х after a space, on its own
    if tok == "х":
        return None, 3.5 if prev.startswith(" ") else 2.4  # bare х, word-internal or start
    if tok in ("ах", "ех"):
        return None, 2.9  # word endings -ах, -ех
    if tok in ("ух", "их"):
        return None, 2.0 if tok == "ух" else 1.5  # word endings -ух, -их
    if len(tok.strip()) == 2 and tok.strip()[0] in KH:
        return None, 2.9  # short syllables хи, хо, ха
    if any(c in KH for c in tok):
        return None, 0.2  # other pieces of words containing х
    if prev and prev[-1] in KH and tok in ("а", "е", "им", "у"):
        return None, 1.3  # the piece right after a х inside a word (арх|е, стих|е)
    if tok in (" а", " г", " А", " Г"):
        return None, 0.75  # word-initial Cyrillic а and г, weakly
    return None, 0.0

