    'who': -0.6, 'whether': -0.9, 'as': -0.6,
    'from': -0.85, 'in': -0.7, 'by': -0.7,
    'through': -1.2, 'into': -1.4, 'out': -1.8,
    'all': -2.3, 'more': -1.0, 'here': -1.2,
    'below': -0.7, 'you': -0.7,
}
VIEW_COMPLEMENTS = {
