"""Layer-0 MLP down-projection unit 6041: a 'math-reference' detector.

It goes strongly negative where a mathematical text is about to cite an equation:
the open bracket of "(3.1)", "Eq. (", "formula (", "[(" and similar, and words such as
"equation", "expression", "derived" that set up such a citation. It is near zero in
prose, code, names and Chinese text. The strength of the bracket response grows with
how mathematical the recent text is, measured as a decaying average over the last
~20 tokens of math-like tokens (math words, symbols, letters, digits).
"""
import re

READS = ()
DECAY = 0.95
OPEN = {"(", " (", "[", " [", "(\\", " (\\", "[(", "[@", "({", "(["}
STRONG = {"equation", "equations", "expression", "expressions", "Eq", "eq", "derived",
          "inequality", "bound", "integral", "theorem"}
WEAK = {"result", "results", "term", "form", "condition", "conditions", "solution",
        "formula", "follows", "using"}
MATH_WORDS = {"equation", "equations", "expression", "expressions", "formula", "result",
              "results", "theorem", "lemma", "proof", "let", "define", "defined", "given",
              "derive", "derived", "satisfy", "satisfies", "solution", "function", "integral",
              "term", "terms", "inequality", "condition", "conditions", "bound", "Eq", "eq",
              "where", "we", "using", "follows", "then", "thus", "hence", "so", "assume",
              "show"}


def is_cjk(s):
    return re.search(r"[一-鿿぀-ヿ가-힯]", s) is not None


def is_math_like(s):
    t = s.strip()
    if t in MATH_WORDS or re.search(r"[=$\\^_{}+*/<>|]", s):
        return True
    return re.fullmatch(r"[a-zA-Z]|\d+", t) is not None


def step(carry, prefix, upstream):
    toks = prefix.token_strings
    tok = toks[-1]
    if len(toks) == 1 or prefix.document_ids[-1] != prefix.document_ids[-2]:
        mathiness = 0.0          # new document: forget the earlier text
    else:
        mathiness = carry        # decayed average of math-like tokens so far
    new_carry = DECAY * mathiness + (1 - DECAY) * float(is_math_like(tok))

    value = 0.0
    if tok in OPEN:
        prev = toks[-2] if len(toks) > 1 else ""
        if is_cjk(prev):
            weight = 0.0         # brackets after Chinese text are not equation citations
        elif re.fullmatch(r"\s?[a-z]+", prev):
            weight = 1.0         # after an English word, as in "is (", "from (", "formula ("
        else:
            weight = 0.5
        value = -(0.8 * mathiness * weight + 0.05)
    elif tok.strip() in STRONG:
        value = -0.6
    elif tok.strip() in WEAK:
        value = -0.25
    return new_carry, value

