"""Estimate the negative signal on isolated B-D choice labels and letter variables."""
import re

READS = ()
UPPER = {"B": (-0.60, -0.31), "C": (-0.35, -0.15), "D": (-0.46, -0.24)}
LOWER = {"b": (-0.17, -0.31), "c": (-0.40, -0.28), "d": (-0.45, -0.15)}
LABEL = re.compile(r"(?:^|[\s(])[A-Ea-e][.)]\s")
PAREN_LABEL = re.compile(r"\([a-e]\)\s")


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    history = "" if carry is None or carry[0] != doc else carry[1]
    token = prefix.token_strings[-1]
    letter = token.strip()
    value = 0.0
    if letter in UPPER:
        value = UPPER[letter][int(token[:1].isspace())]
    elif letter in LOWER:
        value = LOWER[letter][int(token[:1].isspace())]
    if value:
        recent = history[-180:]
        if LABEL.search(recent) or PAREN_LABEL.search(recent):
            value = -1.0 if letter.isupper() else -0.8
        elif letter.islower() and recent.rstrip().endswith("("):
            value = -0.8
        elif letter == "b" and recent.rstrip().lower().endswith("a and"):
            value = -0.8
    return (doc, (history + token)[-220:]), value

