    '<|endoftext|>': (0.0336, 0.0507),
    '<|im_start|>': (0.0193, -0.0721),
    '<|im_end|>': (-0.0152, -0.1153),
    '<tool_call>': (-0.0748, -0.1684),
    '::': (-0.0390, 0.0297),  # Scope-resolution punctuation.
