    doc = prefix.document_ids[-1]
    initial = carry is None or carry != doc
    s = prefix.token_strings[-1]
    value = 0.0097 if initial else -0.00065
    if s in MARKERS:
        value = MARKERS[s][int(initial)]
    elif initial and s.strip() == 'Title':
        value = 0.3454
    elif '《' in s:  # Chinese opening book-title punctuation.
        value = 0.0268 if initial else -0.1373
    elif '\xa0' in s:
        value = 0.0213 if initial else -0.0326
    elif s and not s.strip('·'):
        value = -0.017 * min(len(s), 3)
    elif s and not s.strip():
        if '\n' in s:
            value = -0.0104 if initial else 0.0046
        elif '\t' in s:
