"""Layer-0 MLP output feature 6045, as a word-level program.

The feature is nearly silent: most tokens give a value within a few hundredths of 0.
Its clearest responses are to particular words, grouped here by meaning:

* Group and collection nouns that usually take "of" ("a collection of", "an assortment
  of", "a pair of", "a couple of", "a bunch of", "plenty of", "a series of"), and topic
  nouns ("the subject", "the topic", "a tale", "attention", "focus"): about +0.18.
* Cooking and food words ("cooker", "cooking", "ingredients", "tsp", "served",
  "recipe", "meal", "delicious"): about +0.09.
* Words for something usual or recurring ("usual", "annual", "weekly", "occasional"):
  about +0.12.
* Names common in news text ("New York", "United States", "Trump", "Obama", "George",
  "James", ...): about -0.12.

Every other token predicts 0. The program reads only the current token. It leaves out
the long tail of rare words, whose sign is idiosyncratic, so it explains only about 1%
of the feature's variance on held-out text.
"""

READS = ()

GROUP_NOUNS = {
    "collection", "assortment", "pair", "couple", "bunch", "plenty", "series",
    "selection", "variety", "mixture", "trio", "duo", "crowd", "group",
}
TOPIC_NOUNS = {"subject", "subjects", "topic", "topics", "tale", "tales", "attention", "focus"}
FOOD_WORDS = {
    "cooker", "cooking", "cook", "cooked", "ingredients", "tsp", "serving", "served",
    "kitchen", "recipe", "dish", "meal", "delicious", "cuisine", "tablespoon",
}
USUAL_WORDS = {"usual", "annual", "weekly", "occasional"}
NAME_WORDS = {
    "States", "York", "Coast", "Africa", "Church", "Angeles", "Trump", "Obama",
    "George", "James", "India", "Carolina", "Detroit", "Britain", "Manchester",
    "Vegas", "Singapore", "Burma", "Zimbabwe", "Haiti",
}


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip()
    if word in GROUP_NOUNS or word in TOPIC_NOUNS:
        return carry, 0.18
    if word in FOOD_WORDS:
        return carry, 0.09
    if word in USUAL_WORDS:
        return carry, 0.12
    if word in NAME_WORDS:
        return carry, -0.12
    return carry, 0.0

