"""A sparse token-form approximation, not a single semantic-topic detector.

Strong responses mark carriage-return-heavy prefixes, an opening empty //
comment, tool-response boundaries, and specific code forms. A few lexical
side responses are included: small English word classes and Thai/Korean
word fragments. Unknown vocabulary and most contextual variation are omitted.
A document-local position, return count, and 48-character tail are retained.
"""
READS = ()

SPORTS = frozenset('sport sports football baseball hockey tennis match matches'.split())
SEEKING = frozenset(
    'help helps helping support want wants wanted look looks looking '
    'search searching seek seeking'.split()
)
NEGATION = frozenset('no non without neither nor none nothing nobody cannot'.split())
TIME = frozenset('time future moment once again today'.split())
MONEY = frozenset('money currency finance financial bank business cash dollar dollars'.split())
MEMBERSHIP = frozenset('citizenship citizen citizens member members membership'.split())
CONCESSION = frozenset('though although yet'.split())
MILITARY = frozenset('military militia army defense defence'.split())

WORD_CLASSES = (
    (SPORTS, -0.08), (SEEKING, 0.06), (NEGATION, 0.044),
    (TIME, -0.045), (MONEY, 0.06), (MEMBERSHIP, 0.056),
    (CONCESSION, 0.08), (MILITARY, 0.12),
)


def local_response(token, tail, first, return_fraction):
    if token == '\r':
        return 0.15 + 1.46 * return_fraction ** 2
    if token == '//\n':
        return 1.84 if first else -0.02

    # Opening and closing tool replies have opposite signs.
    if token == '<tool_response>':
        return -0.14
    if token == '</tool_response>':
        return 0.147
    if token == '<think>':
        return 0.124
    if token in {'</think>', '<tool_call>', '</tool_call>'}:
        return -0.06

    # Specific source-code constructs, rather than all code indiscriminately.
    if token == '_modules':
        return 0.16
    if token == '(crate':
        return 0.48 if tail.endswith('pub') else 0.21
    if token in {' crate', ' cargo'}:
        return 0.21
    if token == '.util':
        return 0.25 if tail.endswith('java') else 0.02
    if token == '.font':
        return 0.59 if tail.endswith('pygame') else 0.23
    if token == '.out':
        return 0.14
    if token == '.rs':
        return 0.087
    if token == '/tests':
        return -0.19
    if token == '/testify':
        return 0.77
    if token == '/repository':
        return 0.17
    if token == ' strconv':
        return 0.43
    if token.lstrip(' .') == 'toString':
        return -0.16
    if token.strip() == 'endl':
        return -0.13

    # The incomplete Thai 'for' and Korean 'dawn' are already identifiable.
    if token == 'หร':
        return 0.51 if tail.endswith('สำ') else 0.05
    if token == '벽':
        return 0.46 if tail.endswith('새') else 0.12
    if token == 'ไว':
        return 0.39
    if token == '牢':
        return 0.38

    if token in {'.com', '.org', '://'}:
        return -0.05
    if token == 'www':
        return -0.117
    if token == '!':
        return -0.043
    if token == '?':
        return 0.028
    if token == '\t':
        return 0.014
    if token == '\xa0':
        return -0.021

    # Match whole space-prefixed words, not pieces inside identifiers.
    if token.startswith(' '):
        word = token[1:]
        for words, value in WORD_CLASSES:
            if word in words:
                return value
    return -0.0006


def step(carry, prefix, upstream):
    doc = int(prefix.document_ids[-1])
    if carry is None or carry[0] != doc:
        position, returns, tail = 0, 0, ''
    else:
        _, position, returns, tail = carry
    token = prefix.token_strings[-1]
    returns += token == '\r'
    value = local_response(token, tail, position == 0,
                           returns / (position + 1))
    return (doc, position + 1, returns, (tail + token)[-48:]), value

