"""Predict small positive responses for a few rare text patterns.

Most positions return zero. The exceptions are carriage returns at row or
document starts, a comment marker after an end-of-text token, and a handful
of recognizable code or language fragments. Their estimates are shrunk
because these patterns are sparse and not every occurrence is a strong one.
"""

READS = ()
SHRINK = 0.44


def step(carry, prefix, upstream):
    strings = prefix.token_strings
    token = strings[-1]
    previous = strings[-2] if len(strings) > 1 else ""

    value = 0.0
