    elif token == "/testify" and previous == "/stretchr":
        value = 0.74
    elif token == "(crate" and previous.strip() == "pub":
        value = 0.51
    elif token == ".font" and previous.strip() == "pygame":
        value = 0.59
    elif token == "หร" and previous == "สำ":
        value = 0.51
    elif token == "벽" and previous.strip() == "새":
        value = 0.46
    elif token == "牢":
        value = 0.54
    elif token == " �" and previous == "💬":
        value = 0.60

    return None, SHRINK * value

programs.haiku:
"""Layer-0 MLP down_proj component 6048: a "object-after-gerund" detector.

It is quiet almost everywhere, and goes strongly negative on the word that
directly follows a gerund (a verb ending in -ing) when that word is a
determiner, pronoun or particle that starts the object or complement of the
verb: "Writing [a] love letter", "setting [up] WiFi", "phasing [out] my",
"catching [the] support", "Enjoying [our] articles".
Particles (up, out, down, back, about, through) are strongest.
"""

READS = ()

PARTICLES = {"up", "out", "down", "back", "about", "through", "over", "off", "forward"}
DETERMINERS = {
    "the", "a", "an", "this", "that", "these", "those", "your", "our", "my",
    "his", "her", "their", "its", "all", "some", "any", "them", "it", "me", "us",
    "something", "more", "together",
}
PREPOSITIONS = {"to", "with", "on", "in", "for", "into", "from", "at"}


def step(carry, prefix, upstream):
    if len(prefix.token_ids) < 2 or prefix.document_ids[-1] != prefix.document_ids[-2]:
        return None, 0.0
    prev = prefix.token_strings[-2].strip().lower()
    cur = prefix.token_strings[-1].strip().lower()
    if not prev.endswith("ing") or len(prev) < 5:
        return None, 0.0
    if cur in PARTICLES:
        return None, -2.3
    if cur in DETERMINERS:
        return None, -1.4
    if cur in PREPOSITIONS:
        return None, -0.8
    return None, 0.0

programs.luna:
"""A small cue for a conspicuous word-to-word transition.

The component often drops when an English -ing ending is followed by a short
determiner or preposition. Other ordinary letter words after the same ending
are near zero on broader samples; the many other contexts are left at zero.
"""

READS = ()

DETERMINERS = {
    "a", "an", "the", "this", "that", "these", "those", "my", "your",
    "his", "her", "its", "our", "their", "some", "any", "each", "every",
    "all", "another", "no", "one",
}

PREPOSITIONS = {
    "about", "above", "after", "around", "at", "before", "behind",
    "below", "between", "by", "down", "during", "for", "from", "in",
    "into", "of", "off", "on", "onto", "out", "over", "through", "to",
    "under", "up", "with", "within", "without",
}


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    document = prefix.document_ids[-1]
    previous = None
    if carry is not None and carry[0] == document:
        previous = carry[1]

    value = 0.0
    if previous is not None and previous.strip().lower().endswith("ing"):
        word = token.strip().lower()
        if word in DETERMINERS:
            value = -1.32
        elif word in PREPOSITIONS:
            value = -0.84
        elif any(char.isalpha() for char in word):
            value = 0.05
        elif word and not any(char.isalnum() for char in word):
            value = 0.01

    return (document, token), float(value)

programs.sol:
"""A short-piece spelling signal, not a topic or meaning detector.

Track the unfinished alphabetic word and how many tokens have spelled it.
The third and later pieces fire most, especially when both the current and
previous pieces are short. Length, writing system, vowels and consistent
case set the strength; some familiar English and Russian suffix strings
reduce it. Other tokens are mostly zero. Standalone accent marks and NUL
tokens preserve the word; Arabic accent marks get a small positive value.
Dotted capitals continue an abbreviation. Documents and changes of alphabet
reset the word. These are approximate, fitted amplitudes.
"""
from functools import lru_cache
import unicodedata

READS = ()
ALPHABETS = ('LATIN', 'CYRILLIC', 'GREEK', 'ARABIC',
             'ARMENIAN', 'GEORGIAN', 'KATAKANA')
ENGLISH_SUFFIXES = frozenset(('ed', 'ly', 'ic', 'ity', 'ous', 'ive',
                              'ant', 'ance', 'ical'))
RUSSIAN_ADJECTIVE_ENDINGS = frozenset(('ный', 'ные', 'ных', 'ной',
                                     'ное', 'ная', 'ную', 'ая'))
# Character-length effects; the last entry also covers longer pieces.
CURRENT_LENGTH = (0.39, 0.29, 0.10, -0.03, -0.09, -0.06)
PREVIOUS_LENGTH = (0.25, 0.07, 0.0, -0.065, -0.085, -0.06, -0.05)


@lru_cache(maxsize=8192)
def script(s):
    letters = [c for c in s if c.isalpha()]
    for name in ALPHABETS:
        if letters and all(name in unicodedata.name(c, '') for c in letters):
            return name
    return ''


def spelling(word, pieces, previous, s, alphabet):
    n = min(len(s), 6)
    if alphabet == 'KATAKANA':
        return 0.12 if n == 1 else 0.06 if n == 2 else 0.0
    if not alphabet:
        return 0.0
    vowels = sum(c.lower() in 'aeiou' for c in s) / len(s)
    if pieces >= 2:
        value = CURRENT_LENGTH[n - 1]
        value += PREVIOUS_LENGTH[min(max(len(previous), 1), 7) - 1]
        value += 0.09 * (pieces >= 3) + 0.10 * vowels
        if alphabet in ('GREEK', 'ARMENIAN', 'GEORGIAN'):
            value += 0.07 + 0.20 * (n == 1)
        elif alphabet == 'CYRILLIC':
            value += -0.05 + 0.05 * (n == 1)
        elif alphabet == 'ARABIC':
            value += -0.04 + 0.06 * (n == 1)
        elif not s.isascii():
            value += 0.09
        if word.isupper() and s.islower():
            value = -0.05
        elif not word.isupper() and s.isupper():
            value = 0.0
        elif word.isupper() and s.isupper():
            value += 0.09
            if alphabet == 'CYRILLIC':
                value += 0.28 if pieces == 2 else 0.45
    elif previous.isalpha():
        value = (0.20, 0.13, 0.04, 0.0, 0.0, 0.0)[n - 1]
        value += {'GREEK': 0.32, 'ARABIC': 0.19, 'CYRILLIC': -0.04,
                  'ARMENIAN': 0.32, 'GEORGIAN': 0.32}.get(alphabet, 0.0)
        if word.isupper() and s.islower():
            value -= 0.07
        elif word.isupper() and s.isupper():
            value += 0.27 if alphabet == 'CYRILLIC' else 0.07
    elif pieces:
        value = {'LATIN': 0.025, 'CYRILLIC': -0.09, 'GREEK': -0.18,
                 'ARABIC': -0.08, 'ARMENIAN': -0.10,
                 'GEORGIAN': -0.10}[alphabet] + 0.02 * vowels
        if word.isupper() and s.isupper():
            value += 0.08
    else:
        value = 0.02
    if word and not s.isupper():
        if alphabet == 'LATIN':
            value -= 0.10 * (s in ENGLISH_SUFFIXES) + 0.06 * (s == 'ing')
        elif alphabet == 'CYRILLIC':
            value -= 0.16 * (s in RUSSIAN_ADJECTIVE_ENDINGS)
    return value


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        word, pieces, previous = '', 0, ''
    else:
        word, pieces, previous = carry[1:]
    s = prefix.token_strings[-1]
    if s == '\x00':
        return (doc, word, pieces, previous), -0.02
    if s.startswith('.') and s[1:].isupper() and word.isupper():
        s = s[1:]
    marks = bool(s) and all(unicodedata.category(c).startswith('M') for c in s)
    if marks:
        value = 0.35 if 'ARABIC' in unicodedata.name(s[0], '') else 0.0
        return (doc, (word + s)[-100:], pieces + 1, previous), float(value)
    wordlike = bool(s) and all(
        c.isalpha() or unicodedata.category(c).startswith('M') for c in s
    )
    alphabet = script(s) if wordlike else ''
    if alphabet and word and script(word) != alphabet:
        word, pieces, previous = '', 0, ''
    value = spelling(word, pieces, previous, s, alphabet)
    if wordlike:
        word, pieces = (word + s)[-100:], pieces + 1
    else:
        parts = s.split()
        word = parts[-1] if parts and parts[-1].isalpha() else ''
        pieces = int(bool(word))
    return (doc, word, pieces, s), float(value)

programs.haiku:
"""Short word-internal letter fragments (mid-word subword pieces).

layers.0.mlp.down_proj:6049 fires on a letter-only token that has no leading space and
directly follows another such token, i.e. the 2nd, 3rd, ... piece of a word that the
tokenizer split into several pieces. Its strength depends on

- the script of the piece: Greek strongest (1.0), then Arabic and accented Latin (0.7),
  Cyrillic (0.6), plain ASCII and other scripts (0.4), and nothing for CJK, kana, Hangul
  or Thai;
- the piece's length: one or two letters fire fully, three letters at 0.45, four or more
  not at all.

Every other token (word starts, spaces, punctuation, digits) predicts 0.
Only the previous token and a per-row run counter are carried, so it runs in one pass.
"""

import unicodedata

READS = ()

# Activation strength of a fragment by script (the script of its first letter).
STRENGTH = {"GREEK": 1.0, "ARABIC": 0.7, "LATIN": 0.7, "CYRILLIC": 0.6, "ASCII": 0.4}
# Scripts that never trigger it.
SILENT = {"HANGUL", "HIRAGANA", "KATAKANA", "CJK", "THAI"}


def is_fragment(token):
    """A letters-only piece with no leading space: it continues the word before it."""
    return token[:1] != " " and token.isalpha()


def strength(token):
    first = token.strip()[:1]
    if first.isascii():
        return STRENGTH["ASCII"]
    script = unicodedata.name(first, "UNKNOWN").split()[0]
    if script in SILENT:
        return 0.0
    return STRENGTH.get(script, 0.4)


def length_factor(token):
    n = len(token)
    if n <= 2:
        return 1.0
    if n == 3:
        return 0.45
    return 0.0


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    # carry: (document id of the previous token, how many fragments end there in a row)
    prev_doc, prev_run = carry if carry is not None else (None, 0)
    if prev_doc != doc:
        prev_run = 0
    run = prev_run + 1 if is_fragment(token) else 0
    if run >= 2:
        value = strength(token) * length_factor(token)
    else:
        value = 0.0
    return (doc, run), float(value)

programs.luna:
"""Predict from the token's spelling: non-letter pieces get 0; Greek pieces get 0.60,
Arabic 0.11, and Cyrillic 0.07. Other letter pieces get 0.12 when the preceding token
is alphabetic in the same document and script, and 0.055 otherwise. This coarse rule
approximates a script-sensitive word-fragment response."""

import unicodedata

READS = ()


def _script(text):
    for char in text:
        if char.isalpha():
            name = unicodedata.name(char, "")
            for script in (
                "GREEK", "CYRILLIC", "ARABIC", "HEBREW", "LATIN",
                "HIRAGANA", "KATAKANA", "CJK", "HANGUL", "THAI",
                "DEVANAGARI", "ARMENIAN", "GEORGIAN",
            ):
                if script in name:
                    return script
            return "other"
    return "none"


def step(carry, prefix, upstream):
    piece = prefix.token_strings[-1]
    if not piece.isalpha():
        return None, 0.0

    script = _script(piece)
    if script == "GREEK":
        return None, 0.60
    if script == "ARABIC":
        return None, 0.11
    if script == "CYRILLIC":
        return None, 0.07

    t = prefix.position
    if (
        t > 0
        and prefix.document_ids[-1] == prefix.document_ids[-2]
        and prefix.token_strings[-2].isalpha()
        and _script(prefix.token_strings[-2]) == script
    ):
        return None, 0.12
    return None, 0.055

programs.sol:
"""A lexical attempt signal, strongest on 'try'.

Inflections and synonyms are weaker, as are words for tentative alternatives
and persistence. Related Chinese/Japanese words and fragments also respond. The 'ry'
fragments and drying words are weaker lexical lookalikes.
The short carried tail recognizes 'let me/let's try', 'trying to', and code;
it resets at document boundaries. Unlisted tokens predict zero.
"""
import re

READS = ()
ATTEMPTS = {
    'trying': 4.75, 'tried': 4.6, 'tries': 4.15,
    'attempt': 1.9, 'attempting': 2.15, 'attempted': 1.75,
    'attempts': 1.45, 'retry': 1.25, 'retries': 1.25,
}
TENTATIVE = {'maybe', 'perhaps', 'hopefully'}
TRANSITIONS = {'finally', 'beyond'}
PERSISTENCE = {'keep', 'kept', 'keeping', 'keeps'}
# Try/test characters, attempt phrases, and Japanese do/try auxiliaries.
EAST_ASIAN_ATTEMPTS = {
    '试': 3.3, '試': 3.3, '尝': 3.3, '尝试': 4.9, '嘗試': 4.9,
    '看看': 0.95, '尽量': 1.65, '盡量': 1.65,
    'み': 0.85, 'やり': 1.7, 'やら': 1.5,
    '试试': 5.8, '试着': 4.2, '试图': 2.6,
}

SMALL_CUES = TENTATIVE | TRANSITIONS | PERSISTENCE


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    tail = carry[1] if carry is not None and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    word = token.strip().lower()
    if word.lstrip('._') == 'try':
        value = 7.3
        if word.startswith(('.', '_')):
            value = 7.2
        elif token.startswith('\t'):
            value = 8.8
        elif re.search(r"let(?: me|['’]s)$", tail.lower()):
            value = 8.45
        elif tail and tail[-1].isspace():
            value = 8.05
        elif token == 'try':
            if tail.endswith('re'):
                value = 3.05
            elif tail.endswith('\\n'):
                value = 6.15
            elif tail and tail[-1].isalpha():
                value = 4.8
            else:
                value = 7.6
    elif word == 'to' and re.search(r'\btrying$', tail.lower()):
        value = 0.26
    elif word in ATTEMPTS:
        value = ATTEMPTS[word]
        if word == 'tries' and not token[:1].isspace():
            value = 1.35
    elif word in {'trial', 'trials'}:
        value = 0.55
    elif word in SMALL_CUES:
        value = 0.9
    elif word in {'possibly', 'probably'}:
        value = 0.4
    elif word in EAST_ASIAN_ATTEMPTS:
        value = EAST_ASIAN_ATTEMPTS[word]
    elif word == 'dry':
        value = 1.1
    elif word in {'干', '乾'}:
        value = 0.85
    elif word in {'fry', 'dried'}:
        value = 0.4
    elif token == 'ry':
        value = 1.35
    elif word in {'ried', 'ries', 'stry', 'etry'}:
        value = 0.85
    else:
        value = 0.0
    return (doc, (tail + token)[-32:]), value

programs.haiku:
"""Component layers.0.mlp.down_proj:6050: a "trying" detector.

It fires on the word "try" and its relatives, at the token itself:
  - bare "try" (any capitalisation, with or without a leading space): strongest;
  - the inflections "trying", "tried", "tries", and the Chinese 尝试;
  - the "attempt" family, and the Chinese/Japanese words for trying (试, 試, やり);
  - weakly, "retry", "dry", "trial", and a few hedges that often sit beside a
    proposed attempt ("perhaps", "maybe", "keep", "beyond", "finally").
Everything else gets 0. The program reads only the current token: the component's
activation is almost entirely a function of which word it is (a word lookup alone
explains about 90% of its variance on training text; this word-class version explains
about 70%). Values are mean activations per word class, read off training text.
"""

READS = ()

TRY = {"try"}
TRYING = {"trying", "tried", "tries", "尝试"}
ATTEMPT = {"attempt", "attempts", "attempted", "attempting"}
TRY_OTHER = {"试", "試", "やり"}
WEAK = {"retry", "dry", "ry", "trial"}
HEDGE = {"perhaps", "maybe", "keep", "keeps", "kept", "keeping", "beyond", "finally"}


def value(word):
    """The activation for one token, given its text decoded alone."""
    word = word.strip().lower()
    if word in TRY:
        return 7.6
    if word in TRYING:
        return 4.5
    if word in ATTEMPT:
        return 1.8
    if word in TRY_OTHER:
        return 3.3
    if word in WEAK:
        return 1.1
    if word in HEDGE:
        return 0.9
    return 0.0


def step(carry, prefix, upstream):
    # Stateless: each position is scored from its own token alone.
    return carry, float(value(prefix.token_strings[-1]))


def main():
    """Print the predicted activation for some example words."""
    for word in ["try", " tried", "attempt", "perhaps", "country"]:
        print(repr(word), value(word))


if __name__ == "__main__":
    main()

programs.luna:
"""Mark attempts, tentative wording, and a small set of continuation words."""

READS = ()

ATTEMPT_VERBS = {"try", "tried", "tries", "trying"}
HEDGES = {"perhaps": 0.96, "maybe": 0.86, "possibly": 0.48, "probably": 0.29,
          "hopefully": 0.69}
KEEP_WORDS = {"keep", "keeps", "kept", "keeping"}


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().lower()
    if word == "try":
        return None, 7.0
    if word in ATTEMPT_VERBS:
        return None, 4.6
    if word.startswith("attempt"):
        return None, 1.7
    if word == "retry":
        return None, 1.25
    if word in {"trial", "trials"}:
        return None, 0.55
    if word in KEEP_WORDS:
        return None, 0.9
    if word == "beyond":
        return None, 0.94
    if word == "finally":
        return None, 0.65
    return None, HEDGES.get(word, 0.0)

programs.sol:
"""A selective lexical detector for personnel and organizational workplaces.

Employees and staff give the strongest responses. Workers, organizational
units, facilities, and staffing activities give smaller ones. Tool-result and
thinking delimiters are a separate response. This deliberately ignores most
small token-specific effects and contextual variation.
"""
READS = ()

EMPLOYEES = {
    'employee', 'employees', 'staff', 'staffer', 'staffers', 'layoffs',
    '員工', '职工', '职员', 'スタッフ', 'mitarbeiter', 'сотрудник',
}
WORKFORCE = {
    'worker', 'workers', 'workforce', 'coworkers', '工作人员', '劳动力',
    '劳动者', 'работник', '同事', '同事们', 'сотруд',
}
UNITS = {
    'subsidiary', 'subsidiaries', 'affiliates', 'faculty', 'headquarters',
    'headquartered', '总部', '子公司', '分公司', '控股', 'conglomer',
}
FACILITIES = {'facility', 'facilities', '工厂', '基地', '厂房', '车间'}
STAFFING = {'staffing', '实习', '实习生', '上班', '加班', '人力资源'}
PERSONNEL = {'personnel', '人员', 'crew', 'workplace', 'workplaces', 'amenities'}
GROUPS = (
    (1.25, EMPLOYEES), (0.82, WORKFORCE), (0.93, UNITS),
    (0.55, FACILITIES), (0.65, STAFFING), (0.38, PERSONNEL),
    (0.53, {'colleague', 'colleagues'}),
    (0.40, {'operations', 'operational', '运营', 'affiliate'}),
    (0.22, {'factory', 'factories', 'plant', 'plants'}),
    (0.12, {'employer', 'employers', 'employment', 'company', 'companies', '公司'}),
)
MARKERS = {
    '<tool_response>': 1.106, '</tool_response>': 0.231,
    '<think>': -0.126, '</think>': -0.182, '<|im_end|>': -0.033,
}


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    word = token.strip().strip('._/').lower()
    if token in MARKERS:
        return None, MARKERS[token]
    if word == '员工':
        return None, 1.80
    if word in {'mployee', 'loyee'}:  # Tokenized endings of EMPLOYEE.
        return None, 0.98
    for value, words in GROUPS:
        if word in words:
            if word in {'employee', 'worker'}:
                value *= 0.80
            if word in {'employee', 'worker', 'factory'} and not token[:1].isspace():
                value *= 0.70
            if token.strip() == 'Headquarters':
                value = 0.52
            return None, float(value)
    return None, 0.0

programs.luna:
"""A lexical sketch of the component's sparse personnel/workplace responses.

It assigns fixed positive guesses to employee and staff terms, smaller guesses
to related roles, workplaces, and employment words, and a separate high guess
to the serialized tool-response marker. All other tokens get zero.
"""

READS = ()

DIRECT_STAFF = (
    "employee", "worker", "staff", "员工", "員工", "职工", "職工",
    "工作人员", "スタッフ",
)

RELATED_STAFF = (
    "faculty", "personnel", "colleague", "coworker", "workforce",
    "сотруд", "同事", "人员",
)


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1].casefold().strip()

    if token == "<tool_response>":
        return None, 1.10
    if token == "</tool_response>":
        return None, 0.23

    if any(stem in token for stem in DIRECT_STAFF):
        return None, 1.03
    if any(stem in token for stem in RELATED_STAFF):
        return None, 0.58
    if any(stem in token for stem in ("headquarter", "subsidiar", "总部")):
        return None, 0.85
    if "operation" in token:
        return None, 0.17
    facilities = ("facility", "factory", "workplace", "campus", "工厂", "基地")
    if any(stem in token for stem in facilities):
        return None, 0.24
    if any(stem in token for stem in ("employ", "hiring", "hire", "payroll")):
        return None, 0.15
    pay_and_labor = ("labor", "labour", "wage", "salary", "employer", "compensation")
    if any(stem in token for stem in pay_and_labor):
        return None, 0.09
    if any(stem in token for stem in ("teacher", "nurse", "patient", "student")):
        return None, 0.09
    return None, 0.0

"""A lower-amplitude estimate of a sparse pronoun and reference-word feature.

First-person words receive the largest positive estimates, with smaller
values for other pronouns and possessive markers; all other tokens get zero.
"""

READS = ()

FIRST_PERSON = {"i", "we", "us"}
SECOND_PERSON = {"you"}
OTHER_PRONOUNS = {
    "he", "she", "they", "them", "him", "her", "it", "this", "that",
    "what", "who", "which",
}


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().casefold()
    if word == "i":
        return None, 1.625
    if word in FIRST_PERSON:
        return None, 1.625
    if word == "me":
        return None, 0.975
    if word in SECOND_PERSON:
        return None, 1.17
    if word in OTHER_PRONOUNS or word in {"'s", "’s", "的"}:
        return None, 0.65
    return None, 0.0

"""A sparse spelling cue dominated by Cyrillic в (“in/at”)."""

READS = ()


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    folded = token.casefold()

    # The most common and strongest match is the Russian word “в” (in/at).
    if folded == " в":
        return None, -2.9
    if folded == "в":
        return None, -2.9 if token == "В" else -1.65

    word = folded.strip(" \t\n.,;:()[]{}$*-_")
    if word == "β":
        return None, -1.6
    if word == "beta":
        return None, -1.3
    if word == "v":
        return None, -0.5

    # Short w-like letter tokens in Thai, Japanese and Arabic.
    if token == "ว":
        return None, -2.3
    if token == "ワ":
        return None, -1.4
    if token == " و":
        return None, -1.5
    if token == "و":
        return None, -0.5

    return None, 0.0

programs.sol:
"""A lexical 'by/source' signal, not a test of who actually did an action.

English by and Chinese 由 dominate. Casing, attached punctuation, and
arithmetic collocations change the strength. Related source particles
and compounds containing 由 also respond at different strengths; 路由 ('routing') is a weaker use.
Most other words are ignored, rather than fitting their small responses.
"""
import re

READS = ()
SOURCE_PARTICLES = {'从', '從', 'から', 'より'}


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    word = token.strip()
    previous = ''
    same_document = prefix.position > 0 and (
        prefix.document_ids[-1] == prefix.document_ids[-2]
    )
    if same_document:
        previous = prefix.token_strings[-2].strip().lower()

    value = 0.0
    if word.lower() == 'by':
        value = 1.24 if word == 'By' else 0.82
        if word == 'BY':
            value = 0.71
        elif token == 'by':
            value = 0.94
        # Arithmetic uses are weaker than the agent/method preposition.
        if previous == 'divided':
            value = 0.08
        elif previous in {'multiplied', 'divisible'}:
            value = 0.29
        elif previous == 'step':
            value = 0.55
    elif word == '-by':
        value = 0.72
    elif word in {'/by', '_by', '.by', '_By'}:
        value = 1.20
    elif re.search(r'(?:^[Bb]y[A-Z]|[a-z]By$)', word):
        value = 0.90             # CamelCase grouping/selection names.
    elif word in {'thereby', 'whereby', 'hereby'}:
        value = 0.31
    elif word == '由':
        value = 7.00
        if same_document and prefix.text_prefixes[-2].endswith('路'):
            value = 3.32
    elif word in {'是由', '不由'}:
        value = 5.60             # 'is by' / 'cannot help'.
    elif word == '由此':
        value = 4.05             # 'from this', hence/therefore.
    elif '由' in word:
        value = 0.16 if '路由' in word else 1.05
    elif word == '被':
        value = 0.84
    elif word.lower() == 'von':
        value = 0.91 if token == ' von' else 0.51
    elif word in SOURCE_PARTICLES:
        value = 1.03
    elif word in {'からの', 'によって', '부터'}:
        value = 0.54
    elif word == '依':
        value = 0.66
    elif word == 'por':
        value = 0.29
    elif word.lower() == 'from' and token != ' from':
        value = 0.32             # Capitalized or attached source keyword.
    elif word.lower() == 'courtesy':
        value = 1.17
    elif word == 'of' and previous == 'courtesy':
        value = 0.51
    return None, value

programs.luna:
"""Mark a few observed source/agent words: English, Chinese, German and Japanese."""

READS = ()

SOURCE_OR_AGENT_WORDS = {"by", "被", "von", "から"}


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1].strip().casefold()
    return None, 0.85 if token in SOURCE_OR_AGENT_WORDS else 0.0

programs.sol:
"""A lexical containment/possession detector, not a semantic parser.

Forms of 'contain', translations, and split spellings are strongly negative;
'have' and composition verbs are weaker. Include-forms and 'been' are mildly
positive. Articles/prepositions immediately following containment or
composition cues share the negative signal. Whole 'container' nouns are
excluded from the strong verb rule. Position adjusts document-start strength,
and state resets at document boundaries. Unrecognized tokens receive zero.
"""
READS = ()

CONTAIN = {
    'contain': -5.55, 'contains': -5.46, 'containing': -5.01,
    'contained': -4.53, 'containment': -4.14,
}
POSSESSION = {
    'have': -0.64, 'has': -0.65, 'had': -0.55, 'having': -0.60,
    'possess': -0.69, 'possesses': -0.69, 'possessed': -0.60,
    'possessing': -0.60, 'comprises': -0.59, 'comprising': -0.50,
    'consist': -0.80, 'consists': -0.82, 'consisted': -0.82,
    'consisting': -0.80,
}
# Contain/include, content, or storage: words and roots in several languages.
TRANSLATIONS = {
    '含': -8.18, '含有': -5.67, '包含': -3.95, '包含了': -2.93,
    '蕴含': -5.33, '不含': -4.75, '富含': -3.43, '中含有': -4.34,
    '涵': -3.96, '蕴': -2.59, '藏': -1.44, '内涵': -1.75,
    '含量': -2.46, '含义': -2.05, '含まれ': -3.49,
    '포함': -2.65, 'chứa': -3.30, 'contiene': -3.93,
    'contenido': -2.24, 'contenu': -1.23, 'zaw': -2.61,
    'содерж': -5.04, 'содержа': -4.66, 'содержит': -3.43,
    'одерж': -3.30,
}
CONT_ENDINGS = {
    'ain': -4.94, 'ains': -6.90, 'aining': -5.90,
    'ained': -5.04, 'ainment': -5.50, 'ainer': -1.17,
    'ient': -2.65, 'iene': -2.51, 'ienen': -2.38,
    'enant': -3.08, 'ener': -1.85, 'endo': -2.23,
}
POSITIVE = {'include': 0.20, 'included': 0.29, 'including': 0.18,
            '#include': 0.39, 'been': 0.16}
COMPOSITION = {'consist', 'consists', 'consisted', 'consisting',
               'composed', 'comprised'}
MODIFIERS = {'mainly', 'mostly', 'largely', 'entirely', 'primarily',
             'solely', 'wholly', 'partly', 'almost'}


def lexical(token):
    word = token.strip()
    bare = word.lstrip('._-[(')
    lower = bare.lower()
    if lower in CONTAIN:
        value = CONTAIN[lower]
        if lower == 'contains':
            if token.startswith('.'):
                value = -4.65 if bare[:1].isupper() else -5.08
            elif bare == 'Contains':
                value = -5.90 if token[:1].isspace() else -6.58
        elif lower in ('contain', 'contained') and not token[:1].isspace():
            value += 0.8
        return value + (0.85 if token.startswith('-') else 0.0)
    if lower.startswith('contains') and lower[8:]:
        return -1.35 if bare[:1].isupper() else -2.70
    if token.startswith('.') and lower == 'includes':
        return -1.02
    if bare.startswith(('has', 'Has')) and len(bare) > 3:
        if bare[3].isupper():
            return -1.0
    if lower in POSSESSION:
        return POSSESSION[lower] - (0.25 if token.startswith(('.', '_')) else 0)
    if lower in ('cont', 'conten'):
        return -2.92 if lower == 'conten' else -1.40
    if lower in ('content', 'contents'):
        return -0.35 if lower == 'content' else -1.20
    if lower in ('assertin', 'tocontain'):
        return -2.40
    if lower in ('startswith', 'endswith', 'hasownproperty', 'haskey', 'hasprefix'):
        return -1.0
    return TRANSLATIONS.get(word, POSITIVE.get(word.lower(), 0.0))


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        position, previous, last_value, expects_of = 0, '', 0.0, False
    else:
        _, position, previous, last_value, expects_of = carry
        position += 1
    token = prefix.token_strings[-1]
    word = token.strip().lower().lstrip('._-[(')
    value = lexical(token)
    if '�' in token:  # Recover a containment character completed across tokens.
        end = prefix.text_prefixes[-1][-1:]
        if end == '含':
            value = -10.8
        elif end in ('蕴', '涵', '藏'):
            value = TRANSLATIONS[end]
    if not token[:1].isspace():
        if previous == 'cont' and word in CONT_ENDINGS:
            value = CONT_ENDINGS[word]
        elif previous == 'conten' and word.isalpha():
            value = -1.0
        elif previous in ('содерж', 'одерж', 'содержа') and word.isalpha():
            value = -3.8 if word == 'ать' else (-0.78 if word == 'им' else -2.6)
        elif previous == '含' and word in ('む', '蓄'):
            value = -2.43 if word == 'む' else -3.80
    if previous in CONTAIN and word in ('a', 'the', 'an'):
        value -= abs(last_value) * (0.16 if word == 'an' else 0.22)
    if previous == 'contained' and word in ('in', 'within'):
        value -= 1.26 if word == 'in' else 0.68
    if expects_of and word == 'of':
        value -= 0.64
    expects_of = word in COMPOSITION or (expects_of and word in MODIFIERS)
    if value < -2.0:
        value *= 1.45 if position == 0 else 0.98 + 0.17 / (1 + position / 16)
    if word in ('have', 'has', 'had', 'having') and position == 0:
        value *= 0.70
    return (doc, position, word, value, expects_of), float(value)

programs.haiku:
"""Verbs of containing, having and consisting; a mild positive for 'include'."""
READS = ()

CONTAIN = {"contain", "contains", "containing", "contained", "含", "涵"}
HAVE = {"have", "has", "had", "having"}
CONSIST = {"consist", "consists", "consisting", "consisted", "comprise", "comprises", "comprising", "comprised", "possess"}
CONTENT = {"cont", "content", "contents", "containment"}
INCLUDE = {"include", "#include"}

def step(carry, prefix, upstream):
    w = prefix.token_strings[-1].strip().lower().lstrip(".-#")
    if w in CONTAIN:
        return None, -5.2
    if w in HAVE:
        return None, -0.6
    if w in CONSIST or w in CONTENT:
        return None, -0.8
    if w in INCLUDE:
        return None, 0.3
    return None, 0.0

programs.luna:
"""Approximate sparse word responses around having and containment.

Contain-family verbs have a large negative response; have-family verbs and
some related verbs are smaller, while include/included/including are positive.
"""
READS = ()


def step(carry, prefix, upstream):
    raw = prefix.token_strings[-1].strip().lower()
    word = raw
    word = word.strip(".,!?;:'\"`#-_/\\()[]{}<>* ")

    if word in {"contain", "contains", "contained", "containing"}:
        return None, -5.4
    if word == "containment":
        return None, -4.3
    if word in {"have", "has", "had", "having"}:
        if word == "had":
            return None, -0.56
        if word == "having":
            return None, -0.60
        return None, -0.65
    if word in {"possess", "possesses", "possessed", "possessing"}:
        return None, -0.70
    if word in {"consist", "consists", "consisted", "consisting"}:
        return None, -0.78
    if word == "contents":
        return None, -1.15
    if word == "content":
        return None, -0.40
    if raw.startswith(".includes"):
        return None, -1.08
    if word in {"include", "included", "including"}:
        return None, 0.23
    return None, -0.005

programs.sol:
"""Calendar-name tokens and calendar fragments, not semantic date recognition.

Title-case month and weekday abbreviations give the strongest negative values,
even when the token is part of an unrelated word. Lower-case forms are weaker;
'may' is treated as a modal verb. Carry continues a calendar response through
an abbreviation period/comma, a space, and the first numeric token, then stops.
Spaces after 'at', 'on', or 'line' also receive small negative values. Positive
exceptions are 'month of', website suffixes, and 'very/pretty much'. All state
resets between packed documents. Most other tokens return zero.
"""
import calendar

READS: tuple[str, ...] = ()
MONTHS = frozenset(calendar.month_name[1:])
DAYS = frozenset(calendar.day_name)
ABBR = dict(zip(calendar.month_abbr[1:],
                (-3.3, -4.2, -2.5, -4.1, -1.85, -3.4,
                 -3.9, -3.7, -4.15, -4.0, -3.55, -3.9)))
ABBR.update(zip(calendar.day_abbr,
                (-3.9, -6.6, -6.1, -5.3, -6.7, -3.3, -3.15)))
MONTH_GAP = dict(zip(calendar.month_name[1:],
                    (0.35, 0.13, -0.34, -0.17, -1.8, -0.14,
                     -0.12, -0.17, 0.03, 0.12, 0.07, 0.46)))


def calendar_token(word, spaced):
    if word in MONTHS:
        return (-1.85 if word == 'May' else -1.15), 'month', MONTH_GAP[word]
    if word in DAYS:
        value = -0.7 if word == 'Sunday' else -1.15
        if word in {'Saturday', 'Wednesday'}:
            value = -1.4
        return value, 'day', -0.2
    if word == 'Sept':
        return -2.0, 'short', -2.1
    title = word.title()
    if title == 'May':  # Lower-case "may" is normally a modal verb.
        return (-0.03 if word.islower() else -0.8), '', 0.0
    if title in ABBR:
        if word.istitle():
            gap = -4.0 if title in calendar.month_abbr else -3.0
            return ABBR[title], 'short', gap
        value = -0.6 if title == 'Mar' else -1.35
        if not spaced:
            value *= 0.7
        return value, '', 0.0
    if title in MONTHS | DAYS and word.islower():
        return -0.65, '', 0.0
    return 0.0, '', 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, '', '', '', 0.0)
    _, previous, kind, phase, gap = carry
    token = prefix.token_strings[-1]
    word = token.strip()
    bare = word.lstrip('-/.')
    value, new_kind, new_gap = calendar_token(bare, token.startswith(' '))
    if new_kind:
        if bare != word:
            value *= 0.5 if word.startswith('.') else 0.8
        if not token.startswith(' '):
            new_gap -= 0.3
        return (doc, word, new_kind, 'name', new_gap), float(value)
    new_phase = ''
    if kind and phase in {'name', 'period'} and token == ' ':
        value = gap
        new_phase = 'gap'
    elif kind == 'short' and phase == 'name' and token in {'.', '.,'}:
        value, gap, new_phase = -1.1, -1.8, 'period'
    elif kind and phase in {'name', 'gap'} and word.isdigit():
        value = -0.95 if gap < -2.5 else (0.27 if kind == 'month' else -0.2)
        if kind == 'month' and gap < -1.0:
            value = -0.26
    elif kind and phase == 'name' and token == ',':
        value = {'short': -1.4, 'month': 0.55, 'day': -0.05}[kind]
        gap, new_phase = (-2.0 if kind == 'short' else -0.2), 'period'
    elif kind == 'month' and phase == 'name' and token == ' of':
        value = 2.0
    elif token == ' ' and previous.lower() in {'at', 'on', 'line'}:
        value = -0.65 if previous.lower() == 'on' else -0.5
    elif token in {'.com', '.org', '.net', '.edu'}:
        value = 1.1 if previous == 'github' else 0.35
    elif word == 'much' and previous.lower() in {'very', 'pretty'}:
        value = 1.4 if previous.lower() == 'very' else 1.7
    return (doc, word, kind if new_phase else '', new_phase, gap), float(value)

programs.haiku:
"""Short-form date detector for layers.0.mlp.down_proj:6060.

What the component does: it goes strongly negative inside short-form dates such as
"Sep 19", "Dec. 5", "Mon 3 Feb" or "Aug 2001". The main trigger is the month or
weekday abbreviation (" Sep", " Dec", " Mon", ...). Full names ("September",
"Monday") give a weaker negative. Right after the abbreviation the space, a period
and the day digit are also pushed negative, and a space after "at", "on" or "line"
gets a small push, since those often lead into a date. Everything else stays at 0.

Predicted activation: a hand-set value per token class, with the state "how many
tokens since the last date name" carried from position to position. The state resets
at each document boundary.
"""

# Abbreviated month and weekday names (lower case). A capitalised one is a strong cue.
ABBREVIATED = {
    "jan", "feb", "mar", "apr", "jun", "jul", "aug", "sep", "sept", "oct", "nov", "dec",
    "mon", "tue", "wed", "thu", "fri", "sat", "sun",
}
# Full month and weekday names.
FULL_NAMES = {
    "january", "february", "march", "april", "june", "july", "august", "september",
    "october", "november", "december", "monday", "tuesday", "wednesday", "thursday",
    "friday", "saturday", "sunday",
}
# Words after which a space often leads into a date.
DATE_LEADS = {"at", "on", "line"}
READS = ()


def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1]
    word = tok.strip()
    # carry = (previous token, tokens since the last abbreviated date name or None)
    prev, since = carry if carry is not None else ("", None)
    if len(prefix.document_ids) > 1 and prefix.document_ids[-1] != prefix.document_ids[-2]:
        prev, since = "", None
    gap = since + 1 if since is not None and since < 3 else None

    if word == "May":
        value = -1.8
    elif word.lower() in ABBREVIATED:
        value = -3.5 if word[:1].isupper() else -1.4
    elif word.lower() in FULL_NAMES:
        value = -1.1
    elif gap == 1 and tok == " " and prev.strip() == "May":
        value = -1.8
    elif gap == 1 and tok == " ":
        value = -3.2
    elif gap == 1 and tok == ".":
        value = -1.1
    elif gap == 2 and tok.isdigit():
        value = -0.7
    elif gap == 2 and tok == " ":
        value = -1.9
    elif tok == " " and prev.strip().lower() in DATE_LEADS:
        value = -0.5
    else:
        value = 0.0

    if word.lower() in ABBREVIATED:
        since = 0
    else:
        since = gap
    return (tok, since), value

programs.sol:
"""A lexical zero/emptiness detector.

Zero words and selected multilingual spellings give large negative values;
empty/nil words and zero-like symbols give weaker ones. The digit 0 mainly
responds at the start of a numeral or decimal group, not in its interior.
An initial all-zero run is an exception. Spelling fragments also respond,
even in unrelated words. Ordinary tokens predict zero.

Only a short text suffix and an initial-zero-run flag are carried across
positions; both reset at document boundaries.
"""
import re

READS = ()


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    same_doc = carry is not None and carry[0] == doc
    tail = carry[1] if same_doc else ''
    initial_zeros = carry[2] if same_doc else True
    token = prefix.token_strings[-1]
    word = token.strip()
    # A byte fragment may complete the Chinese character for zero.
    if '\ufffd' in token and prefix.text_prefixes[-1].endswith('零'):
        word = '零'
    core = word.lstrip('_.-').lower()
    value = 0.0
    if word in {'0', '０'}:
        if not tail or initial_zeros:
            value = -1.45
        elif re.search(r'\\[xu][0-9a-fA-F]+$', tail):
            value = -0.5
        elif tail[-1].isdigit():
            value = 0.05
        elif tail[-1] in '.,':
            value = -1.1
        elif tail[-1].isspace():
            if tail.rstrip()[-1:].isdigit():
                value = -1.45
            elif tail.rstrip()[-1:].isalpha():
                value = -2.45
            else:
                value = -2.2
        elif tail[-1] in '([{':
            value = -2.25
        else:
            value = -1.95
    elif core == 'zero':
        if word.startswith('.'):
            value = -5.3
        elif word.startswith(('_', '-')):
            value = -5.2 if not word.isupper() else -6.5
        else:
            if word == 'Zero':
                value = -7.0
            elif word == 'ZERO':
                value = -5.0
            else:
                value = -6.0
    elif core in {'zeros', 'zeroes'}:
        value = -2.6 if word.startswith('.') else -3.7
    elif core == 'nonzero':
        value = -3.5
    elif word == '零':
        value = -7.6
    elif core in {'empty', 'blank', 'vacant'}:
        value = -1.35
    elif core == 'nil':
        value = -0.75
    elif word in {'∅', '○', '₀', '空'}:
        value = -1.0
    elif word == 'éro':
        value = -5.1 if tail.lower().endswith('z') else -1.7
    elif core == 'ero':
        if tail.lower().endswith('z'):
            value = -6.0
        else:
            value = -1.8 if word.isupper() else -2.2
    elif core == 'eros':
        value = -5.5 if tail.lower().endswith('z') else -1.3
    elif core == 'zer':
        value = -1.6 if token[:1].isspace() else -0.8
    elif word == 'ゼ':
        value = -2.2
    elif word == 'ロ' and tail.endswith('ゼ'):
        value = -3.9
    if core in {'zero', 'zeros', 'zeroes'} and tail.lower().rstrip().endswith(
        ('leading', 'trailing')
    ):
        value -= 1.5
    carry = (doc, (tail + token)[-40:], initial_zeros and token == '0')
    return carry, value

programs.haiku:
"""Draft 4: the word 'zero' (any case or language), 'empty'/'nil'/'blank', and a
number-initial digit 0 (a '0' not preceded by a digit)."""
READS = ()

def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1]
    prev = prefix.token_strings[-2] if len(prefix.token_strings) > 1 else ""
    word = tok.strip("-_. ").lower()
    if word == "zero" or tok == "零":
        return None, -6.0
    if "zero" in word:
        return None, -4.0
    if word in ("empty", "nil", "blank"):
        return None, -1.4
    if tok == "0" and not prev[-1:].isdigit():
        return None, -1.1 if prev[-1:] in ".," else -2.1
    return None, 0.0

programs.luna:
"""Flag written zeroes and a few explicit ways of writing zero or absence.

The strongest recurring cue is the standalone digit 0; this small rule predicts
its typical negative activation and leaves other text at zero.
"""

READS = ()

_DIGIT_ZERO = {"0", "０"}
_ZERO_WORDS = {"zero"}
_ABSENCE_MARKS = {"empty", "∅"}


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1].strip()
    folded = token.casefold()
    if token in _DIGIT_ZERO:
        return None, -1.7
    if folded in _ZERO_WORDS:
        return None, -6.5
    if folded in _ABSENCE_MARKS:
        return None, -1.2
    return None, 0.0

programs.sol:
"""A negative lexical reading signal, not a judgment about sentence meaning.

Recognize read and relatives, code input-reading names, and reading words in
several languages. Token fusion and spelling matter (even bread activates).
A small negative echo reaches a following article, object word, or suffix.
State resets between documents; other tokens predict zero.
"""
import math
import re

READS = ()
# English inflections, derivatives, and closely related reading vocabulary.
WORDS = {
    'read': -6.2, 'reading': -5.4, 'reads': -5.1,
    'reader': -3.9, 'readers': -4.1, 'readings': -3.8, 'unread': -4.0,
    'readonly': -3.0, 'readable': -3.4, 'readability': -3.2,
    'readme': -1.3, 'ready': -0.3, 'readily': -0.67, 'readiness': -1.0,
    'bread': -2.4, 'tread': -1.2, 'fread': -2.7, 'imread': -2.8,
    'load': -0.85, 'library': -0.4, 'literary': -0.5, 'bookstore': -1.0,
}
VERBS = frozenset(('read', 'reading', 'reads'))
ECHO = {' the': -0.95, ' of': -1.4, ' a': -0.5, ' an': -0.5,
        ' this': -0.5, ' it': -0.5, ' more': -0.5, ' More': -0.8,
        's': -4.0, 'ers': -3.5, 'ings': -2.6, 'able': -2.2}
FOREIGN_VERBS = frozenset(('lesen', 'leer', 'lire', 'leggere'))


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous, tail = '', ''
    if carry is not None and carry[0] == doc:
        _, previous, tail = carry
    token = prefix.token_strings[-1]
    letters = re.sub(r'^[^a-zA-Z]+|[^a-zA-Z]+$', '', token)
    word = letters.lower()
    value = WORDS.get(word, 0.0)
    if word in VERBS:
        if token == letters and letters.islower():
            value += 0.7
