resetting at document boundaries. Unrecognized tokens receive zero.
"""
import unicodedata as ud

READS = ()
DOC_FIELDS = {
    'param': 5.3, 'return': 4.4, 'returns': 3.9,
    'see': 4.1, 'throws': 4.2, 'author': 4.6,
    'property': 3.6, 'Override': 3.6, 'brief': 4.2,
    'since': 3.3, 'example': 3.0, 'package': 3.0,
    'link': 2.3, 'generated': 2.4, 'type': 2.0,
    'description': 2.2, 'var': 2.6, 'file': 2.6,
    'method': 1.7, 'region': 1.8, 'covers': 2.7,
    'details': 4.4, 'exception': 2.4,
    'fn': 1.0, 'code': 1.2, 'ref': 1.1,
    'classmethod': 1.9, 'staticmethod': 1.45,
    'NonNull': 1.6, 'NotNull': 1.7, 'Nullable': 1.1,
}
HTML_TAGS = frozenset('''
a b body br button code dd details div em h head hr html img input label li
font option p pre script select small span strong style table tbody td template
th thead tr tt ul
'''.split())
XML_FIELDS = frozenset('param summary returns remarks exception see'.split())
TEX_COMMANDS = {
    'param': 3.9, 'return': 2.6, 'brief': 3.0, 'see': 2.7,
    'label': 1.35, 'ref': 1.1, 'cite': 0.9, 'caption': 1.45,
    'item': 1.4, 'begin': 0.52, 'end': 0.78, 'display': 0.55,
    'quad': 0.78, 'boxed': 1.4, 'times': 0.6, 'approx': 0.9,
    'over': 0.5, 'frac': -0.13, 'var': 0.55,
}
PARTICLES = frozenset('fill filled filling plug plugged plugging'.split())
COMPLEMENTS = frozenset('''
involved included engaged engage invested believe belief interest investment
participate participated participating participation specialize specialized
part terms
'''.split())


def in_value(previous, first):
    word = previous.strip().lower()
    if first:
        return 0.75
    if word in PARTICLES:
        return -0.22
    if word in ('interested', 'invest'):
        return -0.06
    if word in ('result', 'results', 'resulted', 'resulting', 'put'):
        return 0.04
    if word in COMPLEMENTS:
        return 0.17
    if word in ('and', 'or', 'but'):
        return 0.64
    if previous.endswith(','):
        return 0.59
    if word in ('is', 'are', 'was', 'were', 'be', 'been', 'being'):
        return 0.42
    return 0.57 if word.endswith('ly') else 0.48


def fragment_value(char, spaced):
    category = ud.category(char)
    name = ud.name(char, '')
    if char == '�':
        return 0.1
    if category in ('Sm', 'So'):
        return (1.35 if category == 'Sm' else 1.6) if spaced else 0.8
    if name.startswith('GREEK'):
        return 0.7 if spaced else 0.1
    if name.startswith('CYRILLIC'):
        return 0.45 if spaced else 0.05
    if name.startswith('LATIN'):
        return (0.68 if char.isupper() else 0.28) if spaced else 0.05
    if category in ('Cc', 'Co'):
        return 1.3 if spaced else 0.65
    if category in ('No', 'Mn'):
        return 0.55
    if category.startswith('P'):
        return 1.05 if spaced else 0.25
    if category in ('Zs', 'Cf'):
        return 0.9 if spaced else 0.4
    return 0.0


def step(carry, prefix, upstream):
    doc, token = prefix.document_ids[-1], prefix.token_strings[-1]
    first = carry is None or carry[0] != doc
    previous, spaced = ('', False) if first else carry[1:]
    fragments = bool(token) and all(c == '�' for c in token)
    next_spaced = spaced if fragments else token.startswith(' ') and token.endswith('�')
    value = 0.0
    if token == ' in':
        value = in_value(previous, first)
    elif token in (' In', 'In', '.In'):
        value = 1.11 if first and token == 'In' else 0.66
    elif token in (' IN', 'IN', '-in'):
        value = 0.43
    elif token == 'in':
        value = 0.1 if previous and previous[-1].isalnum() else 0.36
    elif token == '@Override':
        value = 0.94
    elif previous.endswith('@'):
        value = DOC_FIELDS.get(token, 0.0)
    elif previous.endswith('\\'):
        value = 0.63 if token.startswith('[') else TEX_COMMANDS.get(token, 0.0)
    elif previous.endswith(':') and token in ('param', 'return'):
        value = 2.05 if token == 'param' else 1.1
    elif previous.endswith(('<', '</')):
        closing = previous.endswith('</')
        if token in XML_FIELDS:
            value = 1.55 if closing else 2.1
        elif token in HTML_TAGS:
            value = 0.65 if closing else 0.9
    elif previous.endswith('%') and token in ('s', 'd', 'f', 'v', 'q'):
        value = {'s': 1.18, 'd': 0.65}.get(token, 0.43)
    elif fragments and previous.endswith('�'):
        char = prefix.text_prefixes[-1][-1]
        value = fragment_value(char, spaced or previous.startswith(' '))
        if char != '�':
            next_spaced = False
    elif token in ('align', 'aligned') and previous == '{':
        value = 0.8
    elif token == 'style' and previous == 'display':
        value = 0.89
    elif token == '{' and previous in ('label', 'ref', 'cite', 'end'):
        value = 0.6 if previous in ('label', 'ref') else 0.45
    elif token in ('章', '条') and previous:
        # Numbered Chinese/Japanese chapters and articles.
        number = previous.lstrip('第')
        if number and all(c in '零〇一二三四五六七八九十百千万两' or c.isdigit()
                          for c in number):
            value = 2.4 if previous.startswith('第') else 1.45
    elif token in ('...', ' ...'):
        value = 0.27
    return (doc, token, next_spaced), float(value)

