LATEX_ENVIRONMENTS = {"align": 1.0, "itemize": 2.0}


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    word = token.strip()
    folded = word.casefold()

    if folded == "in":
        if word == "in":
            return None, 0.48 if token[:1].isspace() else 0.19
        if word == "IN":
            return None, 0.41 if token[:1].isspace() else 0.09
        return None, 0.66
    if folded == "-in":
