    before = "".join(prefix.token_strings[-8:-1])
    if word == "�":
        return None, 0.145
    tag = word[1:].casefold() if word.startswith("@") else folded
    has_at = word.startswith("@") or before.rstrip().endswith("@")
    if has_at and tag in DOC_TAG_VALUES:
        return None, DOC_TAG_VALUES[tag]

    if folded == "@override":
        return None, 0.96
    if folded == "override" and before.rstrip().endswith("@"):
        return None, 3.15
    if folded == "nonnull" and before.rstrip().endswith("@"):
        return None, 1.8

    if word in CHINESE_HEADING_MARKERS:
