"""Presentational phrases: 'Here's', 'Here is/are', and list introductions.

Emit a negative pulse on the copula following Here/here, stronger for capital
Here and for the contraction. Emit a smaller pulse on the next article or
quantifier after a capital-Here presentation. Below is/are, there's, 'the
following', and 'as follows' have weaker responses. Everything else is zero.
Only the last two tokens are retained, resetting at document boundaries.
"""
READS = ()
CONTRACTIONS = {"'s", '’s'}
COPULAS = CONTRACTIONS | {' is', ' are'}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    token = prefix.token_strings[-1]
    previous, before = ('', '')
    if carry is not None and carry[0] == doc:
        previous, before = carry[1:]
    word = previous.strip()
    value = 0.0

    if word in ('Here', 'here'):
        capital = word == 'Here'
        if token in CONTRACTIONS:
            value = -0.96 if capital else -0.66
        elif token == ' is':
            if capital:
                value = -0.57 if previous == 'Here' else -0.52
            else:
                value = -0.32 if previous == 'here' else -0.19
        elif token == ' are':
            value = -0.38 if capital else -0.14
    elif word in ('Below', 'below'):
        if token == ' is':
            value = -0.32 if word == 'Below' else -0.12
        elif token == ' are':
            value = -0.21 if word == 'Below' else -0.10
    elif word.lower() == 'there' and token in CONTRACTIONS:
        value = -0.18
    elif word.lower() == 'the' and token == ' following':
        value = -0.13
    elif word.lower() == 'as' and token == ' follows':
        value = -0.20

    if before.strip() == 'Here' and previous in COPULAS:
        if token in (' the', ' a', ' an', ' some'):
            value = -0.12 if previous in (' is', ' are') else -0.065

    return (doc, token, previous), value

