programs.sol:
"""An equality/assignment spelling detector.

Single equals signs give a large negative response. Longer preceding token
pieces, leading whitespace in a recent line fragment, and repetition weaken
it. Two counters track tokens containing exactly one '=' and fade over 4 and
64 tokens. All state resets at document boundaries. Related operator spellings
have fixed responses; other text is zero. Small background token effects and
fine distinctions between operator spellings are deliberately left out.
"""
import math

READS = ()


def other_operator(raw):
    s = raw.strip()
    if s == '＝':
        return -3.0
    if s.endswith('=') and s[:-1] and set(s[:-1]) <= set(')]}'):
        return -2.6
    if s in {':=', '&='}:
        return -1.7
    if s in {'+=', '-='}:
        return -0.85
    if s.endswith('->'):
        return -0.85 if s == '->' else -0.65
    if s in {'→', '≈', '≡'}:
        return -0.5 if s == '→' else -0.75
    if s == '=>':
        return -0.23
    if s in {'-->', '==>'}:
        return -0.4
    if s.startswith('=') and s.count('=') == 1:
        rhs = s[1:]
        if rhs in {'-', '('}:
            return -1.1
        if rhs in {'\\', '`'}:
            return -2.25
        if rhs.isalpha():
            return -1.25 if len(rhs) == 1 else -0.75
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, '', '', 0.0, 0.0)
    _, previous, line, fast, slow = carry
    raw = prefix.token_strings[-1]
    value = other_operator(raw)
    if raw in {'=', ' ='}:
        value = -2.60 + 0.082 * min(len(previous.strip()), 15)
        value += 0.33 * (len(line) - len(line.lstrip()) >= 2)
        value += 0.45 * math.log1p(fast) + 0.27 * math.log1p(slow)
        value = max(-3.7, min(-0.4, value))
    elif raw.strip() == '=':
        value = -1.0 if raw.startswith(' ') else -1.25
    single_equals = raw.count('=') == 1
    fast = fast * math.exp(-1 / 4) + single_equals
    slow = slow * math.exp(-1 / 64) + single_equals
    line = (line + raw)[-160:].split('\n')[-1]
    return (doc, raw, line, fast, slow), float(value)

