programs.luna:
"""Approximate a sparse pattern around 'of': quantity words lean negative;
selected count, name, and application links lean positive. Other positions are quiet."""
READS = ()

NEGATIVE_QUANTITIES = {"total", "mean", "average"}
POSITIVE_LINKS = {"couple", "name", "applications"}

def step(carry, prefix, upstream):
    current = prefix.token_strings[-1].strip().casefold()
    if current != "of" or len(prefix) < 2:
        return None, 0.0
    if prefix.document_ids[-2] != prefix.document_ids[-1]:
        return None, 0.0
    previous = prefix.token_strings[-2].strip().casefold()
    if previous in NEGATIVE_QUANTITIES:
        return None, -0.65
    if previous in POSITIVE_LINKS:
        return None, 0.6
    return None, 0.0

programs.haiku:
"""Layer 0 MLP down-projection component 6068: reads the word right after "that".

When "that" is a demonstrative (a pronoun or determiner standing for a thing or time),
the word after it is typically a copula or a time/manner noun: "That's", "that is",
"that day", "that way", "that kind of". The component is strongly positive there.
When "that" is a conjunction ("shows that the ...", "note that if ..."), the word after it
is a determiner, a clause opener or a subject pronoun, and the component is negative.
After "which" or "who", a copula gives a weak positive value. Everything else is 0.
"""

READS = ()

THAT = {" that", " That", "that", "That"}
WHICH = {" which", " who"}

# Strongest: "That's", "that day", "that way", "that night", "that year".
TOP = {"'s", "’s", " day", " way", " night", " year"}
# Strong: copulas, "of", and nouns that follow a demonstrative "that".
STRONG = {" is", " was", " of", " case", " means", " time", " point", " part", " kind",
          " same", " date", " version", " matter", " sounds", " mean", " which"}
# Moderate: modal verbs, "be", and a few other words after a demonstrative.
MEDIUM = {" would", " will", " could", " might", " be", " being", " works", " many", " rule",
          " one", " great", " really", " said", " work", " seems", " includes"}
# Negative after a conjunction "that": determiners, prepositions, commas.
DETERMINER = {" the", " this", " there", " these", " their", " its", " his", " your", " our",
              " any", " every", " each", " no", " some", " all", " both", " such", " an", " a",
              " for", " in", " at", " with", " to", " just", " only", " most", " allows",
              " provides", " God", " women", ","}
# Clause openers after a conjunction "that": strongly negative.
CLAUSE = {" if", " when", " even", " after", " without", " because", " although", " neither",
          " on"}
# Subject pronouns after a conjunction "that": slightly negative.
PRONOUN = {" he", " I", " you", " we", " it", " they", " she"}

# After "which" / "who": a copula is weakly positive, a determiner or pronoun negative.
WHICH_TIER = {" is": 0.4, " was": 0.3, " the": -0.5, " it": -0.4, " I": -0.3, " we": -0.2,
              " they": -0.2, " he": -0.2}


def value_after_that(cur):
    if cur in TOP:
        return 3.5
    if cur in STRONG:
        return 2.2
    if cur in MEDIUM:
        return 1.0
    if cur in DETERMINER:
        return -0.7
    if cur in CLAUSE:
        return -1.8
    if cur in PRONOUN:
        return -0.2
    return 0.0


def step(carry, prefix, upstream):
    # The row's first token has no predecessor; a new document resets the context.
    if len(prefix) < 2 or prefix.document_ids[-2] != prefix.document_ids[-1]:
        return None, 0.0
    before, cur = prefix.token_strings[-2], prefix.token_strings[-1]
    if before in THAT:
        return None, value_after_that(cur)
    if before in WHICH:
        return None, WHICH_TIER.get(cur, 0.0)
    return None, 0.0

programs.luna:
"""Approximate a context cue after 'that': content-like words lean positive."""

READS = ()

FINITE_WORDS = {
    "am", "are", "be", "been", "being", "can", "could", "did",
    "do", "does", "had", "has", "have", "is", "may", "might",
    "must", "shall", "should", "was", "were", "will", "would",
}

CLOSED_WORDS = {
    "a", "an", "and", "at", "but", "by", "cannot", "for", "from", "he",
    "her", "hers", "him", "his", "i", "if", "in", "it", "its",
    "me", "my", "of", "on", "or", "our", "she", "so", "some",
    "that", "the", "their", "them", "these", "they", "this", "those",
    "to", "used", "we", "which", "who", "whose", "you", "your",
}


def step(carry, prefix, upstream):
    """After 'that', favor content-like words over listed function words."""
    doc = prefix.document_ids[-1]
    previous = ""
    if carry is not None and carry[0] == doc:
        previous = carry[1]

    current = prefix.token_strings[-1].strip().casefold()
    value = 0.0
    if previous == "that":
        if current in FINITE_WORDS or current.endswith(("'s", "’s")):
            value = 0.8
        elif current.isalpha() and current not in CLOSED_WORDS:
            value = 0.8
        elif current in CLOSED_WORDS or current and not current[0].isalnum():
            value = -0.5

    return (doc, prefix.token_strings[-1].strip().casefold()), value

programs.sol:
"""Local spelling rules for the component's rare, large positive responses.

The main cases are m/s units, ref-type reference metadata, and Unix drwx
permissions. Other cases are limits, a few compound programming identifiers,
and the Korean enjoyment stem 즐 when completed by a separate byte token.
These are distinct spelling triggers, not one semantic category. Most small
positive and negative activations are deliberately left at zero.
"""
READS = ()


def step(carry, prefix, upstream):
    doc = int(prefix.document_ids[-1])
    previous = carry[1] if carry is not None and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    left = previous.strip()
    value = 0.0

    if token == '/s':
        if previous == ' m':
            value = 0.515
        elif previous == 'm':
            value = 0.37
        elif left in {'cm', 'km'}:
            value = 0.19
        elif left == 'mm':
            value = 0.10
    elif token == '-type' and previous == 'ref':
        value = 0.417
    elif token == 'wx':
        if left == 'dr':
            value = 0.547
        elif left in {'r', '-r'}:
            value = 0.32
    elif token == '_{' and left == 'lim':
        value = 0.42
    elif token == 'utils' and left == 'dist':
        value = 0.94
    elif token == 'users' and left == 'diff':
        value = 0.66
    elif token == 'Commit' and left == 'Rev':
        value = 0.54
    elif token == '.header' and left == 'st':
        value = 0.48
    elif token == ' if' and left == 'dd':
        value = 0.42
    elif token == '\ufffd' and previous == ' \ufffd':
        if prefix.text_prefixes[-1].endswith(' 즐'):
            value = 0.42

    return (doc, token), value

"""A mixed lexical detector, dominated by short ber/bert fragments,
cyber, and -bert endings, rather than a single semantic category.
Other branches recognize specified German particles, about/under,
fiber/labor, digital/virtual and probability words, and typographic runs.
The previous token strengthens Cy+ber and learn+about, and weakens
talk/talking+about. Unmatched tokens receive zero. Carry is reset whenever the document changes.
"""
import math

READS = ()


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    prev = '' if carry is None or carry[0] != doc else carry[1]
    token = prefix.token_strings[-1]
    word = token.strip().casefold()
    boundary = bool(token[:1].isspace())
    value = 0.0

    if word == 'ber':
        value = 2.45 if boundary else 2.65
        if prev.casefold().endswith('cy'):
            value = 5.4
    elif word == 'bert':
        value = 1.05 if boundary else 2.65
    elif word in ('berg', 'bern', 'bers'):
        value = 1.4 if boundary else 1.75
    elif word in ('iber', 'ober', 'uber', 'über'):
        value = 2.2
    elif word in ('aber', 'sober'):
        value = 1.65
    elif word == 'fiber':
        value = 1.8
    elif word in ('fibers', 'fibre', 'amber', 'umber'):
        value = 1.2
    elif word in ('fib', 'fibr'):
        value = 0.55
    elif word == 'ember':
        value = 0.92
    elif word == 'cyber':
        value = 3.65
    elif word.startswith('cyber'):
        value = 1.15
    elif word.endswith('bert') and len(word) > 4:
        value = 1.05
    elif word.endswith('ber') and len(word) <= 6:
        value = 0.9 if word not in ('number', 'member') else 0.0
    elif word in ('hyper', 'yper', 'hypert', 'hypers'):
        value = 1.3
    elif word in ('бер', '伯', '柏'):
        value = 1.5 if boundary else 2.8
    elif word == 'بر':
        value = 1.0 if boundary else 1.5
    elif word in ('ер', 'пер'):
        value = 0.35 if word == 'ер' else 0.64
    elif word in ('about', 'under', 'sobre', 'unter'):
        value = 0.78 if word != 'unter' else 0.60
        if word == 'about':
            if prev.strip().casefold() in ('talk', 'talking'):
                value = 0.25
            elif prev.strip().casefold() == 'learn':
                value = 1.15
    elif word == 'darüber':
        value = 1.55
    elif word in ('labor', 'labour'):
        value = 1.2
    elif word in ('digital', 'virtual'):
        value = 0.85
    elif word == 'probability':
        value = 0.8
    elif word == 'probably':
        value = 0.3
    elif len(word) >= 16 and len(set(word)) == 1 and word[0] in '=_-.':
        value = 0.65 + 0.45 * math.log2(len(word) / 16)
        if '\n' in token:
            value *= 0.3
    elif len(token) >= 64 and set(token) == {' '}:
        value = 0.012 * min(len(token), 85)
    return (doc, token), float(value)

programs.luna:
"""A small lexical approximation to this weak first-layer MLP contribution.

The harvested high-impact examples are often temporal or ordering words and
short discourse/relationship words. This rule gives those words a small
positive score and otherwise predicts no contribution.
"""
READS = ()

TIME_ORDER = {
    "now", "then", "later", "before", "first", "past", "back",
    "beginning", "end", "time", "while",
}
RELATION_WORDS = {
    "if", "yet", "so", "on", "over", "off", "away", "following",
    "part", "own", "possible", "required", "come", "least",
}


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().lower()
    if word in TIME_ORDER:
        return None, 0.20
    if word in RELATION_WORDS:
        return None, 0.12
    return None, 0.0

programs.sol:
"""Detect horizontal padding rather than ordinary indentation after a newline.

Spaces and tabs separating material on one line give a positive signal.
Its size rises with the padding length and tapers for very long runs.
A real preceding newline suppresses it; escaped newlines, comment markers,
and standalone + or - markers weaken it. A trailing newline also weakens
it. State remembers only recent tokens and resets at document boundaries.
"""
from math import exp

READS = ()


def padding(length):
    """Saturating rise for short space runs, with a long declining tail."""
    return 1.75 * (1 - exp(-(length - 0.5) / 4)) * exp(
        -max(length - 20, 0) / 65
    )


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        previous, before_previous = '', ''
    else:
        previous, before_previous = carry[1:]
    token = prefix.token_strings[-1]
    body = token.rstrip('\r\n')
    ends_line = body != token
    value = 0.001

    if body and all(c in ' \t\u00a0' for c in body):
        spaces = body.count(' ')
        tabs = body.count('\t')
        length = len(body)
        if body == ' ' or (ends_line and body == '  '):
            value = 0.0
        elif '\n' in previous:
            value = -0.08 if tabs else -0.025
        else:
            if tabs and spaces:
                value = 0.48 + 0.10 * min(spaces, 5)
                value += 0.16 * min(max(spaces - 5, 0), 2)
                value += 0.035 * min(max(spaces - 7, 0), 12)
                value -= 0.03 * max(spaces - 19, 0)
                value = max(0.25, value)
            elif tabs:
                value = min(1.4, 0.92 + 0.25 * (tabs - 1))
                if previous.isspace():
                    value = -0.025 + 0.225 * (tabs - 1)
            elif '\u00a0' in body:
                value = min(0.7, 0.055 * length)
            else:
                value = padding(length)

            if previous.endswith('\\n'):
                value *= 0.52
            elif previous == 'n' and before_previous.endswith('\\'):
                value *= 0.80
            elif previous.strip() in ('+', '-'):
                value *= 0.48
            elif previous.strip() in ('//', '///', '/*') or (
                previous.strip().startswith('#')
            ):
                value *= 0.33
            elif previous.isspace() and not tabs:
                value *= 0.65
            elif not previous:
                value *= 0.3 if tabs and not spaces else 0.75

            if ends_line and tabs and spaces and body.endswith(' '):
                value = 0.05
            elif ends_line:
                value = (0.035 + 0.17 * (tabs - 1)) if (
                    tabs and not spaces
                ) else 0.45 * value

    elif token.startswith('\t') and token.strip():
        if previous and '\n' not in previous and not previous.isspace():
            value = 0.4

    return (doc, token, previous), float(value)

programs.luna:
"""Estimate the MLP's response to horizontal gaps within a line.

Long spaces and tabs after some text act like separators or alignment in source,
tables, and formatted records; ordinary single spaces and line-start indentation
usually get no prediction. A carried line flag keeps the rule causal across lines.
"""
READS = ()


def _horizontal(ch):
    return ch.isspace() and ch not in "\r\n"


def step(carry, prefix, upstream):
    doc = int(prefix.document_ids[-1])
    if carry is None or carry[0] != doc:
        has_text, last_char = False, ""
    else:
        _, has_text, last_char = carry

    token = prefix.token_strings[-1]
    prediction = 0.0

    if token and has_text and all(_horizontal(ch) for ch in token):
        length = len(token)
        if "\t" in token:
            if last_char != "\t":
                prediction = min(1.6, 0.75 + 0.075 * (length - 1))
            else:
                prediction = 0.1
        elif length >= 3:
            prediction = min(
                1.65,
                0.18 * length + (0.3 if last_char.isspace() else 0.0),
            )

    breaks = max(token.rfind("\n"), token.rfind("\r"))
    if breaks >= 0:
        tail = token[breaks + 1:]
        has_text = any(not ch.isspace() for ch in tail)
        last_char = tail[-1:] if tail else ""
    elif token:
        has_text = has_text or any(not ch.isspace() for ch in token)
        last_char = token[-1]

    return (doc, has_text, last_char), float(prediction)

programs.sol:
"""A spelling-level approximation to a capitalization-transition signal.

Spaced capitalized token starts get a negative response, strongest after
lowercase text. Length, script, and small named word classes set its size;
sentence/number boundaries and recent capital starts reduce it. Smaller
corrections cover hyphenated capitals, unspaced initials, and </think>.
State resets between documents. This is not a proper-name recognizer:
complete words and fragments follow the same spelling rules.
"""
import math
import unicodedata

READS = ()
PREPOSITIONS = set('of in to for by on with at from'.split())
SENTENCE_OPENERS = set('The An A This That These Those My Your Our His Her '
                             'Their Its And Or Of To In For By On At With From '
                             'As See Use'.split())
MONTHS = set('January February March April May June July August September '
             'October November December Jan Feb Mar Apr Jun Jul Aug Sep Sept '
             'Oct Nov Dec'.split())
NAME_PREFIXES = set('New Old North South East West San Saint St Mount Fort '
                     'Upper Lower Los Las Al El'.split())
PROGRAMMING_WORDS = set('None True False String List Set Map Tuple Dict Dictionary '
                 'Array Boolean Bool Integer Int Float Double Char Object'.split())
NAMING_FIELDS = {'NAME', 'PERSON', 'SURNAME', 'FIRSTNAME', 'LASTNAME'}
TITLES = set('Mr Mrs Ms Dr Prof Sir'.split())


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    s = prefix.token_strings[-1]
    if carry is None or carry[0] != doc:
        previous, capitals = '', (False, False, False)
    else:
        previous, capitals = carry[1:]
    word = s.strip()
    p = previous.strip()
    value = 0.0
    if s.startswith(' ') and word and word[0].isupper():
        n = len(word)
        initial = n == 1
        # Longer capitalized pieces are usually weaker than short fragments.
        strength = max(0.24, 0.90 * math.exp(-0.23 * max(0, n - 2)))
        if initial:
            strength = 0.87
        if word.isupper() and not initial:
            strength = 0.37
        if word == 'I':
            strength = 0.14
        elif word in MONTHS:
            strength = 0.84
        elif word in NAME_PREFIXES:
            strength = 1.05
        elif word in TITLES:
            strength = 1.14
        elif word in PROGRAMMING_WORDS:
            strength = 0.22
        elif word in NAMING_FIELDS:
            strength = 0.85
        if word == 'New':
            strength = 1.44
        if 'CYRILLIC' in unicodedata.name(word[0], ''):
            strength = 2.12 if initial else 1.22
        if not p or '\n' in previous or p[-1:] in '.?!' or p.isdigit():
            scale = 0.0
        elif p[0].islower() or (not p[0].isalpha() and p[-1:].islower()):
            scale = 1.0
            if p in PREPOSITIONS:
                scale = 1.21
            elif p == 'the':
                scale = 0.86
        elif p in SENTENCE_OPENERS:
            scale = 0.67 if initial else 0.51
        elif p[0].isupper():
            scale = 0.01 if p.isupper() else (0.55 if initial else 0.24)
        elif p[-1:] == ',':
            scale = 0.73
        elif p[-1:] == ';':
            scale = 0.30
        elif p[-1:] == ':':
            scale = 0.10
        elif p in {'&', '—', '–', '|'}:
            scale = 0.29
        else:
            scale = 0.03
        # A capital start two or three tokens back still dampens the response.
        if capitals[1]:
            scale *= 0.61
        elif capitals[2]:
            scale *= 0.83
        value = 0.025 - strength * scale
    elif len(word) > 1 and word[0] == '-' and word[1].isupper():
        if p and (p[0].islower() or p[0].isupper() and not p.isupper()):
            value = -0.60 * math.exp(-0.20 * max(0, len(word) - 3))
    elif word == '</think>':
        value = 0.39
    elif word and word[0].isupper() and len(word) == 1:
        value = -0.08 if word != 'I' else 0.025
    cap = bool(word and word[0].isupper())
    return (doc, s, (cap, capitals[0], capitals[1])), value

programs.haiku:
"""Layer-0 MLP down-projection component 6074: a "name opener in prose" detector.

The component goes negative on a capitalised word that starts a name or title in running
prose: a token such as " Dr", " New", " M" (in "son of M"), or a Cyrillic capital, placed
right after a lowercase word, or after a comma or an opening bracket as in a list of names
("Paris, London"). The size depends on what comes before it: prepositions, articles and
conjunctions ("of", "to", "in", "by", "the", "de") give the strongest response among
lowercase words, and a name already under way (the word two back is also capitalised, as in
"United States of ...") gives a weaker one. Capitals after a newline, a quote or a full
stop, and code identifiers, stay near zero.

Program: predicts the activation as a fixed value per category. The category values were set
from group means on training rows, not fitted to eval.
"""

READS = ()

FUNCTION_WORDS = set(
    "of in on at by to from with for and or the a an as that between into via over about "
    "after before is are do if when but than de di la du des del der die das und dem den".split()
)
TITLES_AND_MONTHS = set(
    "January February March April May June July August September October November December "
    "Mr Mrs Ms Dr Prof Sir".split()
)


def _word(token):
    return token.lstrip(" -\"'(")


def _is_capital(word):
    return word[:1].isupper()


def step(carry, prefix, upstream):
    n = len(prefix.token_ids)
    if n < 2 or prefix.document_ids[-1] != prefix.document_ids[-2]:
        return carry, 0.0
    raw_prev = prefix.token_strings[-2].strip()
    word = _word(prefix.token_strings[-1])
    if not _is_capital(word):
        return carry, 0.0
    if raw_prev in (",", "("):
        return carry, -0.3
    if not raw_prev[-1:].islower():
        return carry, 0.0
    if "Ѐ" <= word[:1] <= "ӿ":
        return carry, -1.5
    if word in TITLES_AND_MONTHS:
        return carry, -0.7
    if len(word) == 1:
        return carry, -0.6
    two_back_is_capital = n >= 3 and prefix.document_ids[-3] == prefix.document_ids[-1] and _is_capital(
        _word(prefix.token_strings[-3].strip())
    )
    if raw_prev.lower() in FUNCTION_WORDS:
        return carry, -0.3 if two_back_is_capital else -0.5
    return carry, -0.05 if two_back_is_capital else -0.2

programs.sol:
"""Approximate the component's dominant COVER-family response.

Cover and its inflections are strongly negative; coverage is weaker.
Recover, discover, uncover and enclosing/revealing words respond less.
Spelling, capitalization and token boundaries change the strength.
A following function word echoes cover, while a split inflection ending
retains more of it. State resets at document boundaries.
"""
READS = ()

# Values for a token with, and without, a leading word boundary.
COVER = {"cover": (-6.8, -5.3), "covers": (-6.2, -6.0),
         "covered": (-6.0, -2.6), "covering": (-5.95, -4.1),
         "coverage": (-2.9, -2.3)}
CAPITALS = {"Cover": -7.3, "Covers": -6.5, "Covered": -5.8, "COVER": -6.6}
ECHO = {"of": .55, "the": .175, "a": .13, "an": .09,
        "in": .045, "by": .05, "for": .09, "about": .09,
        "your": .05, "their": .05, "them": .05,
        "up": .025, "to": .025, "on": .025}
CHINESE_COVERING = {
    "覆盖": -3.3, "涵盖": -2.85, "涵盖了": -2.45,
    "覆盖率": -2.0, "全覆盖": -1.85, "掩盖": -2.4,
    "封面": -3.9, "盖": -1.7, "蓋": -1.4, "覆": -1.15,
    "包括": -.5, "封": -.6, "罩": -.7,
}
FRAGMENTS = {"cov": -.95, "over": -.5, "overs": -1.7, "covery": -.7}


def relative(word):
    if word.startswith("uncover") or word in {"covert", "undercover"}:
        return -1.6
    if word.startswith("recover"):
        if word.endswith("ed"):
            return -.55
        return -.7 if word.endswith("y") else -1.1
    if word.startswith("discover"):
        return -.3 if word.endswith(("ed", "y")) else -.65
    if word.startswith(("envelop", "encompass")):
        return -.95 if word in {"envelope", "envelopes"} else -1.2
    if word.startswith("reveal"):
        if word.endswith("ed"):
            return -.5
        return -.6 if word.endswith("ing") else -.85
    if word.startswith("conceal"):
        return -.9 if word.endswith("ed") else -.5
    if word in {"include", "includes", "included", "including",
                "contain", "contains", "contained", "containing"}:
        return -.28
    return {"overcome": -1.2, "hover": -.7}.get(word, 0.0)


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    old_word, previous = ("", 0.0)
    if carry is not None and carry[0] == doc:
        _, old_word, previous = carry
    token = prefix.token_strings[-1]
    spelling = token.strip().lstrip("-_.")
    word = spelling.lower()
    value = relative(word)
    if word in COVER:
        value = COVER[word][token == spelling]
        value = CAPITALS.get(spelling, value)
    elif spelling in CHINESE_COVERING:
        value = CHINESE_COVERING[spelling]
    elif token == spelling and word in FRAGMENTS:
        value = FRAGMENTS[word]
    elif word == "cov":
        value = -1.25
    echo = 0.0
    if old_word in COVER and token[:1].isspace():
        echo = previous * ECHO.get(word, 0.0)
    if previous and token == spelling and word in {"ing", "ings", "ed", "s"}:
        value = previous * {"ing": .74, "ings": .43, "ed": .8, "s": .4}[word]
    strength = value if word in COVER or relative(word) else 0.0
    return (doc, word, strength), float(value + echo)

programs.luna:
"""A lexical sketch of a sparse covering/enclosing feature.

It predicts a large negative value for common tokens spelling cover and its
inflections, and smaller values for coverage, uncovering/recovery, discovery,
and a few words about enclosing or including. Ordinary tokens get zero.
"""

READS = ()


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    word = token.casefold().strip()

    if word in {"cover", "covered", "covers", "covering"}:
        return None, -6.2 if token[:1].isspace() else -3.5
    if word == "coverage":
        return None, -2.7
    if word.startswith("uncover"):
        return None, -1.6
    if word.startswith("recover"):
        return None, -0.7
    if word.startswith("discov"):
        return None, -0.55
    if word.startswith(("envelop", "encompass")):
        return None, -0.95
    if word.startswith("覆"):
        return None, -2.0
    if word.startswith("包括"):
        return None, -0.45
    if word == "封":
        return None, -0.8
    if word.startswith(("includ", "contain")):
        return None, -0.1
    return None, 0.0

programs.sol:
"""Detect a few short demonstrative and degree constructions.

The main pulses are on the second token of 'such a/an', 'this is/was',
'these are/were', 'quite a', and PHP's '$this->'. Modals and ordinary
article transitions get weaker responses. Capitalized demonstratives and
those at a document's start get extra weight. Everything else gets zero.
Only the previous token is remembered, and documents reset that memory.
"""
READS = ()

COPULA = {'is': 0.97, 'was': 0.88, 'be': 0.77, 'isn': 0.80, 'wasn': 0.78}
MODALS = {'can': 0.54, 'could': 0.34, 'may': 0.28, 'might': 0.23,
          'will': 0.35, 'would': 0.30, 'has': 0.50}
ARTICLE = {'of': 0.20, 'be': 0.24, 'been': 0.30, 'like': 0.36,
           'have': 0.14, 'had': 0.17, 'not': 0.48, 'without': 0.29,
           'on': -0.18, 'at': -0.15, 'in': -0.08}


def clean(token):
    return token.strip().lstrip('$\'"“‘([{>').lower()


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    reset = carry is None or carry[0] != doc
    previous = '' if reset else carry[1]
    token = prefix.token_strings[-1]
    word, before = clean(token), clean(previous)
    capital = previous.strip().lstrip('$\'"“‘([{>')[:1].isupper()
    value = 0.0
    if before == 'this':
        if word == '->':
            value = 1.70 if previous.startswith(' ') else 2.12
        elif word in COPULA:
            value = COPULA[word] + (0.13 if capital else 0.0)
            if previous == 'This':
                value += 0.10
        elif word in MODALS:
            value = MODALS[word] + (0.08 if capital else 0.0)
    elif before == 'these' and word in ('are', 'were'):
        value = (1.43 if word == 'are' else 1.05) + (0.27 if capital else 0.0)
        if previous == 'These':
            value += 0.20
    elif before == 'such':
        if word in ('a', 'an'):
            value = (3.32 if word == 'a' else 3.22) + (0.53 if capital else 0.0)
        elif word == 'that':
            value = 0.95
    elif before in ('quite', 'many', 'much') and word in ('a', 'an'):
        value = 1.61 if before == 'quite' else 1.2
    elif word in ('a', 'an'):
        value = ARTICLE.get(before, 0.0) * (0.85 if word == 'an' else 1.0)
    elif before in ('some', 'any', 'many') and word == 'other':
        value = {'some': 0.63, 'any': 0.22, 'many': 0.30}[before]
    if reset and word in ('this', 'these'):
        capital = token.strip()[:1].isupper()
        value = (0.45 if word == 'this' else 0.99)
        if capital:
            value += 0.28 if word == 'this' else 0.53
    return (doc, token), float(value)

programs.haiku:
"""Activation of layers.0.mlp.down_proj:6078 (a determiner-context feature).

It fires on the word right after a demonstrative or intensifier, and only when
that next word begins a predicate or a noun phrase:
  'such' + a/an (3.3), 'such' + 'that' (0.95)
  'this' + '->' or '::' (2.0), 'this' + is/was (1.0), 'this' + can/will/would... (0.6)
  'these' + are/were (1.5)
  'quite'/'many'/'much'/'rather'/'really'/'somewhat' + a/an (1.2), + 'of' (0.4)
  'static' + '::' or '->' (1.2); 'kind'/'type' (plural too) + 'of' (0.2)
Everything else is 0. The word matching ignores case and a leading '$'.
"""
READS = ()

ARTICLES = {"a", "an"}
COPULAS = {"is", "was", "are", "were"}
MODALS = {"can", "will", "would", "could", "should", "may", "might", "must"}
ARROWS = {"->", "::"}
INTENSIFIERS = {"quite", "many", "much", "rather", "really", "somewhat"}
KINDS = {"kind", "kinds", "type", "types"}


def _word(s):
    return s.strip().lower().replace("$", "")


def step(carry, prefix, upstream):
    if prefix.position == 0 or prefix.document_ids[-1] != prefix.document_ids[-2]:
        prev = ""
    else:
        prev = _word(prefix.token_strings[-2])
    cur = _word(prefix.token_strings[-1])
    val = 0.0
    if prev == "such":
        val = 3.3 if cur in ARTICLES else 0.95 if cur == "that" else 0.0
    elif prev == "this":
        val = 2.0 if cur in ARROWS else 1.0 if cur in COPULAS else 0.6 if cur in MODALS else 0.0
    elif prev == "these":
        val = 1.5 if cur in COPULAS else 0.0
    elif prev == "static" and cur in ARROWS:
        val = 1.2
    elif prev in INTENSIFIERS and cur in ARTICLES:
        val = 1.2
    elif prev in INTENSIFIERS and cur == "of":
        val = 0.4
    elif prev in KINDS and cur == "of":
        val = 0.2
    return carry, float(val)

programs.luna:
"""Predict the component's recurring phrase cues.

Its clearest positive responses are to “such a/that” and to a demonstrative
followed by a predicate (“This is/was”, “These are”); code's “$this->” is a
related local cue. The component is quiet on most other tokens, so unmatched
contexts get zero.
"""
READS = ()

BE_AFTER_THIS = {"is", "was", "can"}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    token = prefix.token_strings[-1].strip().casefold()
    previous = carry[1] if carry is not None and carry[0] == doc else ""

    value = 0.0
    if previous == "such" and token == "a":
        value = 3.3
    elif previous == "such" and token == "that":
        value = 1.0
    elif previous == "this" and token in BE_AFTER_THIS:
        value = 1.0
    elif previous == "these" and token == "are":
        value = 1.5
    elif previous == "this" and token == "->":
        value = 2.0

    return (doc, token), float(value)
